insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('ois-kinda-hauma-klaane-gaagln-ausn-moos-aufgsaummaed-und-damit-gschbueued', 'Ois Kinda hauma klaane Gaagln ausn Moos aufgsaummäd und damit gschbüüd!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Als Kinder haben wir kleine Gageln aus dem Moos aufgesammelt und damit gespielt!', '[{"kategorie": "wörtlich", "text": "\"Als Kinder haben wir die kugeligen Fruchtstände des Gagelstrauchs aus dem Moos aufgesammelt und damit gespielt!\"  2. Als Kinder haben wir die kleinen runden Dinger aus dem Moos gepflückt und damit gespielt!  3. In unserer Kindheit sammelten wir die kleinen Nüsschen aus dem Moos und spielten damit!"}]'::jsonb, ''),
  ('im-woid-hauma-iwaroi-klaane-gaagln-gseeng-a-zeichn-dass-raeae-in-da-naeae-woan', 'Im Woid hauma iwaroi klaane Gaagln gseeng - a Zeichn, dass Rää in da Nää woan!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Im Wald haben wir überall kleine Gageln gesehen – ein Zeichen, dass Rehe in der Nähe waren!', '[{"kategorie": "wörtlich", "text": "\"Im Wald entdeckten wir zahlreiche Kotbällchen - ein deutliches Zeichen für Rehwild!\"  2. Überall im Wald lagen diese kleinen Rehköttel – da wussten wir, die Rehe sind nicht weit!  3. Überall auf dem Waldboden sahen wir kleine Kotkügelchen - ein sicherer Hinweis auf Rehe!"}]'::jsonb, ''),
  ('in-gaaglschdrauch-oda-wia-de-leit-friara-gsoogd-haum-es-gaagal-haums-im-mittloita-zum-wiazn-von-bia-vawendt', 'In Gaaglschdrauch oda - wia de Leit friara gsoogd haum: ''es Gaagal'' - haums im Mittloita zum Wiazn von Bia vawendt!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Den Gagelstrauch oder - wie die Leute früher gesagt haben: ''das Gagerl'' - wurde im Mittelalter zum Würzen von Bier verwendet!', '[{"kategorie": "wörtlich", "text": "\"In der mittelalterlichen Braukunst war der Gagelstrauch bzw. das \"Gagerl\" ein verbreitetes Würzkraut für Bier!\"  2. Brauereien des Mittelalters setzten das Gagerl regelmäßig als Bitter- und Aromawürzstoff ein!  3. Das Gagerl gehörte im Mittelalter zum Standard der Bierkräuter!"}]'::jsonb, ''),
  ('ois-kinda-hauma-klaane-gaagaln-ausn-moos-aufgsaummaed-und-damit-gschbueued', 'Ois Kinda hauma klaane Gaagaln ausn Moos aufgsaummäd und damit gschbüüd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Als Kinder haben wir kleine Gagerln aus dem Moos aufgesammelt und damit gespielt!', '[{"kategorie": "wörtlich", "text": "\"Als Kinder haben wir die kugeligen Fruchtstände des Gagelstrauchs aus dem Moos aufgesammelt und damit gespielt!\"  2. Als Kinder haben wir die kleinen runden Dinger aus dem Moos gepflückt und damit gespielt!  3. In unserer Kindheit sammelten wir die kleinen Nüsschen aus dem Moos und spielten damit!"}]'::jsonb, ''),
  ('im-woid-hauma-iwaroi-klaane-gaagaln-gseeng-a-zeichn-dass-raeae-in-da-naeae-woan', 'Im Woid hauma iwaroi klaane Gaagaln gseeng - a Zeichn, dass Rää in da Nää woan!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Im Wald haben wir überall kleine Gagerln gesehen – ein Zeichen, dass Rehe in der Nähe waren!', '[{"kategorie": "wörtlich", "text": "\"Im Wald entdeckten wir zahlreiche Kotbällchen - ein deutliches Zeichen für Rehwild!\"  2. Überall im Wald lagen diese kleinen Rehköttel – da wussten wir, die Rehe sind nicht weit!  3. Überall auf dem Waldboden sahen wir kleine Kotkügelchen - ein sicherer Hinweis auf Rehe!"}]'::jsonb, ''),
  ('pfitschigoogaln-wiad-mit-zwaa-muenzn-gschbueued-de-mit-an-lineaeu-iwad-tischplottn-gflitschd-wean', 'Pfitschigoogaln wiad mit zwaa Münzn gschbüüd, de mit an Lineäu iwad Tischplottn gflitschd wean!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Pfitschigogerln wird mit zwei Münzen gespielt, die mit einem Lineal über die Tischplatte geflitscht werden!', '[{"kategorie": "wörtlich", "text": "\"Fingerfußball wird mit zwei Münzen gespielt, die mit einem Lineal über die Tischplatte gesschnippt werden!\"  2. \"Pfitschigogerln, ein traditionelles Münz-Fingerfußballspiel aus Österreich, wird mit zwei Knöpfen oder Münzen gespielt, die mit einem Lineal über die Tischplatte gesschnippt werden!  3. Das sogenannte ''Pfitschigogerln'' – ein Fingerfußballspiel mit Münzen – wird mit zwei Münzen oder auch Knöpfen gespielt, die mit einem Lineal oder Geodreieck über den Tisch geschnippt werden!"}]'::jsonb, ''),
  ('dera-ia-gaagalgoeoewe-jackn-brennd-da-de-netzhaut-aus-de-aung', 'Dera ia gaagalgööwe Jackn brennd da de Netzhaut aus de Aung!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die gagerlgelbe Jacke von ihr brennt dir die Netzhaut aus den Augen!', '[{"kategorie": "wörtlich", "text": "\"Die giftgelbe Jacke von ihr grillt dir die Netzhaut aus den Augen!\"  2. Die knallgelbe Jacke von ihr fackelt dir fast die ganze Netzhaut weg!  3. Die schrillgelbe Jacke knallt so rein, dass du am liebsten eine Sonnenbrille aufsetzen würdest!"}]'::jsonb, ''),
  ('den-sei-giigalfrack-is-so-eng-gschniidn-dass-a-ned-amoi-mea-de-oam-heebm-kau', 'Den sei Giigalfrack is so eng gschniidn, dass a ned amoi mea de Oam heebm kau!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sein Gigerlfrack ist so eng geschnitten, dass er nicht einmal mehr die Arme heben kann!', '[{"kategorie": "wörtlich", "text": "\"Sein Salonfrack spannt so sehr, dass für ihn schon das Händeschütteln zur Herausforderung wird!\"  2. Sein Operettenfrack ist so eng geschnitten, dass ihm keine drei Zentimeter Bewegungsfreiheit bleiben!  3. Der steckt in seinem Dandy-Frack wie ein Pfau, dem man das Rad zusammengebunden hat!"}]'::jsonb, ''),
  ('schau-da-den-giigalfrack-au-wiara-si-wiida-aufbreezld-hod', 'Schau da den Giigalfrack au, wiara si wiida aufbreezld hod!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Schau dir den Gigerlfrack an, wie er sich wieder aufgebrezelt hat!', '[{"kategorie": "wörtlich", "text": "\"Schau dir den Möchtegern-Gigolo an, wie er sich wieder rausgeputzt hat!\"  2. Sieh dir den Leihkavalier da drüben an, wie er sich wieder zurechtgemacht hat!  3. Guck mal - der Hochglanz-Dandy da drüben hat sich ja wieder ordentlich aufpoliert!"}]'::jsonb, ''),
  ('des-gigesgages-mochd-mi-narrisch', 'Des Gigesgages mochd mi narrisch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieses Gigesgages macht mich narrisch!', '[{"kategorie": "wörtlich", "text": "Dieses ewige Hin und Her macht mich verrückt!  2. Dieses sinnlose Herumgeeiere bringt mich noch zum Wahnsinn!  3. Diese ewíge Herumdruckserei raubt mir noch den Verstand!  4. Dieses ewige Hickhack macht mich wahnsinnig!"}]'::jsonb, ''),
  ('i-hob-di-glei-bei-de-googaln', 'I hob di glei bei de Googaln!', '', '', '', 'Wiener Gaunersprache', 'Ich hab dich gleich bei den Gogerln!', '[{"kategorie": "wörtlich", "text": "\"Ich hab dich gleich bei den Eiern!\"  2. (scherzhaft für): Gleich hab ich dich am Wickel!  3. Glei hob I di aum [[Oasch]]!"}]'::jsonb, ''),
  ('des-gickal-kraad-jeede-frua-pinktlich-uma-fuemfe-bessa-ois-jeeda-wecka', 'Des Gickal kraad jeede Frua pinktlich uma fümfe - bessa ois jeeda Wecka!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Das Gickerl kräht jede Früh pünktlich um fünf - besser als jeder Wecker!', '[{"kategorie": "wörtlich", "text": "\"Der Hahn kräht jeden Morgen pünktlich um fünf - besser als jeder Wecker!\"  2. Jeden Morgen um fünf meldet sich der Haushahn – zuverlässiger als jeder Wecker!  3. Der Gockelhahn legt um Punkt fünf Uhr früh los – da braucht keiner einen Wecker!"}]'::jsonb, ''),
  ('a-hoiwads-gickal-mid-an-eadaepfaesolood-mea-brauch-i-ned-zum-glicklichsei', 'A hoiwads Gickal mid an Eadäpfäsolood - mea brauch I ned zum Glicklichsei!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein halbes Gickerl mit Erdäpfelsalat – mehr brauch ich nicht zum Glücklichsein!', '[{"kategorie": "wörtlich", "text": "\"Ein halbes Hähnchen mit Kartoffelsalat – mehr brauch ich nicht zum Glücklichsein!\"  2. Ein halbes Hendl mit Erdäpfelsalat – und ich bin im Himmel!  3. Ein halbes Hühnchen mit Kartoffelsalat - und mein Glückspegel schießt nach oben!"}]'::jsonb, ''),
  ('ob-boochhhendl-broodhendl-oda-grueuehendl-aum-end-liig-i-sowiiso-wiida-schnaufend-wiara-woiross-auf-da-kautsch', 'Ob Boochhhendl, Broodhendl oda Grüühendl - aum End liig I sowiiso wiida schnaufend wiara Woiross auf da Kautsch!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ob Backhuhn, Brathuhn oder Grillhuhn - am Ende lieg ich sowieso wieder schnaufend wie ein Walross auf der Couch!', '[{"kategorie": "wörtlich", "text": "\"Ob Backhuhn, Brathuhn oder Grillhuhn – danach lieg ich sowieso wieder ächzend auf der Couch wie ein träger Seeelefant!\"  2. Ob paniertes, gebratenes oder gegrilltesHuhn – am Schluss hock ich sowieso wieder röchelnd auf der Couch wie ein überfutterter Wal!  3. Ob frittiertes, gebratenes oder gegrilltes Gockelvieh – danach lieg ich sowieso wieder keuchend wie eine Dampflok auf der Couch!"}]'::jsonb, ''),
  ('a-boochans-hendl', 'a boochans Hendl', '', '', '', 'Wiener Küche & Gaumenfreuden', 'ein gebackenes Hendl', '[{"kategorie": "wörtlich", "text": "\"ein gebackenes Huhn\" (von \"gebacken\"=\"paniert\" und [[Hendl]]=\"Huhn\")"}, {"kategorie": "Kulinarik", "text": "Backhuhn, (Deutschland): \"frittiertes Hähnchen\",  \"paniiads Hendl\""}]'::jsonb, 'A boochans, broodans oda grüüds Hendl - und schoo vagiss I a jeede Diät!'),
  ('a-grueueds-hendl', 'a grüüds Hendl', '', '', '', 'Wiener Küche & Gaumenfreuden', 'ein gegrilltes Hendl', '[{"kategorie": "wörtlich", "text": "\"ein gegrilltes Huhn\" (von \"grillen\"=\"brutzeln\" und [[Hendl]]=\"Huhn\")"}, {"kategorie": "Kulinarik", "text": "Grillhuhn, (Deutschland): \"gegrilltes Hähnchen\", \"Grillhähnchen\""}]'::jsonb, 'A boochans, broodans oda grüüds Hendl - und schoo vagiss I a jeede Diät!'),
  ('a-broodans-hendl', 'a broodans Hendl', '', '', '', 'Wiener Küche & Gaumenfreuden', 'ein gebratenes Hendl', '[{"kategorie": "wörtlich", "text": "\"ein gebratenes Huhn\" (von \"braten\"=\"schmoren\" und [[Hendl]]=\"Huhn\")"}, {"kategorie": "Kulinarik", "text": "Brathuhn, (Deutschland): \"gebratenes Hähnchen\", Brathähnchen"}]'::jsonb, 'A boochans, broodans oda grüüds Hendl - und schoo vagiss I a jeede Diät!'),
  ('a-boochans-broodans-oda-grueueds-hendl-und-schoo-vagiss-i-a-jeede-diaet', 'A boochans, broodans oda grüüds Hendl - und schoo vagiss I a jeede Diät!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein gebackenes, gebratenes oder gegrilltes Hendl - und schon vergiss ich eine jede Diät!', '[{"kategorie": "wörtlich", "text": "\"Ein frittiertes, gebratenes oder gegrilltes Hähnchen - und schon vergiss ich jede Diät!\"  2. Ein knuspriges Back-, Brat- oder Grillhuhn – und meine Diät löst sich in Luft auf!  3. Ein knuspriger Hendlvogel, gebacken, gebraten oder gegrillt – und alle meine Diätpläne verabschieden sich!"}]'::jsonb, ''),
  ('im-fitness-schdudio-is-des-skelettgiigal-wiida-iwa-seine-eiganan-schbagettifiass-gschdoipad', 'Im Fitness-Schdudio is des Skelettgiigal wiida iwa seine eiganan Schbagettifiass gschdoipad!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Im Fitnessstudio ist das Skelettgigerl wieder über seine eigenen Spaghetti-Füße gestolpert!', '[{"kategorie": "wörtlich", "text": "\"Im Fitnessstudio stolperte der dürre Gockel wieder mal über seine eigenen Spaghetti-Beine!\"  2. Im Fitnessstudio ist der Skelettgockel erneut über seine eigenen Zahnstocherbeine gefallen!  3. Im Gym ist der selbstverliebte, dürre Gockel wieder über seine eigenen Spaghettihaxen gestolpert!"}]'::jsonb, ''),
  ('sei-giigalhofts-auftreedn-geed-ma-aum-keks', 'Sei giigalhofts Auftreedn geed ma aum Keks!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sein gigerlhaftes Auftreten geht mir auf den Keks!', '[{"kategorie": "wörtlich", "text": "\"Sein gockelhaftes Auftreten geht mir tierisch auf die Nerven!\"  2. Seine dandyhafte Art macht mich wahnsinnig!  3. Sein selbstverliebtes Gehabe hängt mir zum Hals raus!"}]'::jsonb, ''),
  ('i-greif-ins-giigalfuada-wiara-piroot-ind-goidkistn-hauptsoch-iagendwos-im-moong-bevua-da-naeaechste-schnops-kummd', 'I greif ins Giigalfuada wiara Piroot ind Goidkistn - Hauptsoch iagendwos im Moong, bevua da näächste Schnops kummd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich greif ins Gigerlfutter wie ein Pirat in die Goldkiste – Hauptsache irgendwas im Magen, bevor der nächste Schnaps kommt!', '[{"kategorie": "wörtlich", "text": "\"Ich greif ins Studentenfutter wie ein Schatzsucher in die Goldkiste – Hauptsache irgendwas im Magen, bevor der nächste Kurze anrückt.\"  2. Ich stürz mich aufs Studentenfutter wie ein Geier aufs Aas – irgendwas muss ja als Unterlage für die nächsten Schnäpse her!  3. Ich stopf mir Studentenfutter rein wie ein Besoffener Kleingeld in die Jukebox – Hauptsache Unterlage vorm nächsten Hochprozentigen!"}]'::jsonb, ''),
  ('wiara-mit-de-schbitzn-schuach-in-kuazn-sakkoo-da-weidn-hoosn-und-de-knopfschdiifaen-auftauchd-is-hob-i-ma-denkd-schau-da-wos-au-des-giigaltum-leebd-no', 'Wiara mit de schbitzn Schuach, in kuazn Sakkoo, da weidn Hoosn und de Knopfschdiifän auftauchd is, hob I ma denkd: ''Schau da wos au, des Giigaltum leebd no!''', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Wie er mit den spitzen Schuhen, dem kurzen Sakko, der weiten Hose und den Knopfstiefeln aufgetaucht ist, hab ich mir gedacht: ''Schau dir was an, das Gigerltum lebt noch''!', '[{"kategorie": "wörtlich", "text": "\"Als er in spitzen Schuhen, kurzem Sakko und weiter Hose hereinstolzierte, dachte ich nur: ''Schau an, das gute alte Gigerltum lebt noch''!\"  2. Wie er mit seinem Pfauen-Outfit einmarschiert ist, war mir klar: ''Jawohl, das Gigerltum hat überlebt''!\"  3. Als er so herausgeputzt hereinschwebte, dachte ich: ''Heiliger Bim Bam, das Gigerltum lebt wirklich noch''!\""}]'::jsonb, ''),
  ('de-giggld-imma-wiara-buelliche-braut-waunn-da-schaeaef-ins-zimma-kummd', 'De giggld imma wiara bülliche Braut, waunn da Schääf ins Zimma kummd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die giggelt immer wie ''ne billige Braut, wenn der Chef ins Zimmer kommt!', '[{"kategorie": "wörtlich", "text": "\"Die macht auf süß und kichert wie auf Kommando, wenn der Chef ins Zimmer kommt!\"  2. Die fängt sofort an rumzuglucksen, wenn der Chef auftaucht!  3. Sobald der Chef im Raum steht, mutiert sie jedes Mal zur billigen Kicherpuppe!"}]'::jsonb, ''),
  ('dea-giftniigl-is-da-beste-beweis-daafia-dass-charakta-nix-mit-bueuedung-z-tuan-hod', 'Dea Giftniigl is da beste Beweis daafia, dass Charakta nix mit Büüdung z''tuan hod!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieser Giftnigel ist der beste Beweis dafür, dass Charakter nichts mit Bildung zu tun hat!', '[{"kategorie": "wörtlich", "text": "\"Dieser Widerling ist der beste Beweis dafür, dass klug sein und Anstand haben zwei Paar Schuhe sind!\"  2. Dieser Fiesling zeigt perfekt, dass man studiert haben kann und trotzdem ein Arsch bleibt!  3. Diese Giftspritze ist schlau wie sonst was, aber charakterlich unter aller Sau!"}]'::jsonb, ''),
  ('du-dreckika-vafickda-giftniigl', 'Du dreckika, vafickda Giftniigl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du dreckiger, verfickter Giftnigel!', '[{"kategorie": "wörtlich", "text": "\"Du dreckiger, hinterhältiger Giftzwerg!\"  2. \"Du mieser, ätzender Scheißkerl!\"  3.  \"Du widerlicher, abgefuckter Stinkstiefel!\""}]'::jsonb, ''),
  ('dass-di-ned-teischd-dei-neiche-nette-nochbarin-is-a-giftnuudl', 'Dass di ned teischd - dei neiche ''nette'' Nochbarin is a Giftnuudl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dass du dich nicht täuscht - deine neue ''nette'' Nachbarin ist eine Giftnudel!', '[{"kategorie": "wörtlich", "text": "\"Lass dich nicht täuschen, deine neue ''nette'' Nachbarin ist eine Giftnudel!\"  2. Fall nicht drauf rein – deine neue ‚nette‘ Nachbarin ist eine Giftspritze!  3. Glaub ihr kein Wort – deine neue ‚nette‘ Nachbarin ist in Wahrheit eine Giftschlange!"}]'::jsonb, 'Dass di ned teischd!'),
  ('dass-di-ned-teischd', 'Dass di ned teischd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Dass du nicht nicht täuscht!', '[{"kategorie": "wörtlich", "text": "\"Pass auf, dass du dich nicht täuschst!\"  2. \"Hoffentlich irrst du dich nicht!\"  3. \"Hoffen wir mal, dass du richtig liegst!\"  4. \"Nicht, dass der Eindruck trügt!\""}]'::jsonb, ''),
  ('dea-grindniigl-lossd-sei-gschia-wochnlaung-schdee-pfui-teifae', 'Dea Grindniigl lossd sei Gschia wochnlaung schdee - pfui Teifä!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieser Grindnigel lässt sein Geschirr wochenlang stehen - pfui Teufel!', '[{"kategorie": "wörtlich", "text": "\"Dieser Dreckskerl lässt sein Geschirr wochenlang rumstehen – einfach widerlich!\"  2. Dieser widerliche Saubartel lässt sein Drecksgeschirr wochenlang vor sich hinmodern – zum Kotzen!  3. Dieser asoziale Typ zeigt mal wieder sein wahres Gesicht: Geschirr wochenlang stehen lassen – unter aller Sau!"}]'::jsonb, ''),
  ('du-schimplada-eitriga-grindniigl', 'Du schimplada, eitriga Grindniigl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du schimmeliger, eitriger Grindnigel!', '[{"kategorie": "wörtlich", "text": "\"Du versiffter, vergammelter Dreckskerl!\"  2. \"Du verwesender, faulender Drecksack!\"  3. \"Du verlauster, pestbeuliger Mistkerl!\""}]'::jsonb, ''),
  ('ziag-in-finga-ausn-riassl-du-noosnbuara-du-degutanta', 'Ziag in Finga ausn Riassl, du Noosnbuara, du degutanta!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Zieh den Finger aus dem Rüssel, du Nasenbohrer, du degoutanter!', '[{"kategorie": "wörtlich", "text": "\"Zieh den Finger aus der Nase, du widerlicher Nasenbohrer!\"  2. \"Zieh den Griffel aus der Nase, du ekliger Popler!\"  3. Finger raus aus dem Zinken – wir sind hier nicht im Zoo!"}]'::jsonb, ''),
  ('a-echta-noosnbuara-dea-typ-mea-ois-sinnlos-umanaundsitzn-und-lecha-ind-luft-schdiian-bringd-dea-ned-zsaumm', 'A echta Noosnbuara, dea Typ - mea ois sinnlos umanaundsitzn und Lecha ind Luft schdiian, bringd dea ned zsaumm!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein echter Nasenbohrer, der Typ - mehr als sinnlos herumsitzen und Löcher in die Luft stieren, bringt der nicht zusammen!', '[{"kategorie": "wörtlich", "text": "\"Ein echter Taugenichts, dieser Nasenbohrer - mehr als sinnlos rumzusitzen und Löcher in die Luft zu starren, bringt der nicht zusammen!\"  2. Ein fauler Sack, dieser Nasenbohrer - mehr als seinen Hintern plattzusitzen und die Luft anzustarren, kriegt der nicht hin!  3. Ein nutzloser Lump, dieser Nasenbohrer - mehr als Däumchen zu drehen und in die Gegend zu glotzen, bringt der nicht zustande!"}]'::jsonb, ''),
  ('dea-is-ned-nua-lost-bro-des-is-a-nuitschekka-auf-endlevl', 'Dea is ned nua lost, Bro - des is a Nuitschekka auf Endlevl!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Der ist nicht nur lost, Bro - das ist ein Nullchecker auf Endlevel!', '[{"kategorie": "wörtlich", "text": "\"Der ist nicht nur daneben, Bruder - der ist ein wandelndes Blackout der Kategorie ''hoffnungslos''!\"  2. ''Lost'' ist untertrieben, Bruder - der Typ ist ein Volldepp auf Endstufe!  3. Der Kerl ist nicht lost, Bruder, der ist komplett durch – ein absoluter Nullgneißer!"}]'::jsonb, ''),
  ('dea-nuigneissa-is-a-intellektuella-totalausfoi-dea-is-ned-nua-aunungslos-dea-is-komplett-hiantood', 'Dea Nuigneissa is a intellektuella Totalausfoi - dea is ned nua aunungslos, dea is komplett hiantood!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser Nullgneißer ist ein intellektueller Totalausfall - der ist nicht nur ahnungslos, der ist komplett hirntot!', '[{"kategorie": "wörtlich", "text": "\"Dieser Nullchecker ist geistig ein Totalausfall – der ist icht nur ahnungslos, sondern komplett hirntot!\"  2. Diese Flachpfeife ist nicht nur dumm wie Brot, der ist geistig schon kompostiert - ein intellektueller Sargnagel!  3. Der Typ ist nicht nur hirntot, der ist ein lebendes Denkmal der Ahnungslosigkeit - ein Nullchecker, der die Null erfunden hat!"}]'::jsonb, ''),
  ('dea-hod-sein-noosnraummae-aafoch-aufd-scheibm-von-da-bim-gschmiiad-pfui-teifae', 'Dea hod sein Noosnraummä aafoch aufd Scheibm von da Bim gschmiiad - pfui Teifä!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat seinen Nasenrammel einfach an die Scheibe der Tramway geschmiert - pfui Teufel!', '[{"kategorie": "wörtlich", "text": "\"Der hat seinen Nasenrammel einfach an die Tram-Scheibe geschmiert - so ein Dreckschwein!\"  2. Der hat sich den Nasenrotz rausgezogen und direkt an die Tram-Scheibe geklebt – einfach zum Kotzen!  3. Der zieht sich ’nen Rammel und parkt ihn an der Tram-Scheibe – echt unter aller Sau!"}]'::jsonb, ''),
  ('an-noosnraummae-kostn', 'an Noosnraummä kostn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Nasenrammel kosten', '[{"kategorie": "wörtlich", "text": "\"einen Pappenstiel kosten\""}, {"kategorie": "", "text": "\"so gut wie nichts kosten\""}, {"kategorie": "", "text": "\"für einen Apfel und ein Ei zu haben sein\""}, {"kategorie": "", "text": "\"den Geldbeutel nicht jucken\""}, {"kategorie": "", "text": "\"an [[Leachalschas]] kosten\""}]'::jsonb, 'De Reparatua kost an Noosnraummä - do brauchsd ned laung iwaleeng!'),
  ('de-reparatua-kost-an-noosnraummae-do-brauchsd-ned-laung-iwaleeng', 'De Reparatua kost an Noosnraummä - do brauchsd ned laung iwaleeng!', '', '', '', 'Wiener Mechaniker-Slang', 'Die Reparatur kostet einen Nasenrammel - da brauchst nicht lang überlegen!', '[{"kategorie": "wörtlich", "text": "\"Die Reparatur kostet einen Pappenstiel - da brauchst du nicht lange zu überlegen!\"  2. Die Reparatur kostet fast nichts, da musst du nicht groß überlegen!  3. Die Reparatur kostet einen Klacks – da überlegt man nicht, da macht man!"}]'::jsonb, 'an Noosnraummä kostn'),
  ('des-is-echt-unta-olla-sau', 'Des is echt unta olla Sau!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist echt unter aller Sau!', '[{"kategorie": "wörtlich", "text": "\"Das ist echt zum Kotzen!\"  2. \"Das ist eine Riesenschweinerei!\"  3. \"Das ist echt unter jedem Niveau!\"  4. \"Das ist eine bodenlose Frechheit!\""}]'::jsonb, ''),
  ('da-klaane-maxi-woit-da-leararin-heit-sei-noosnmaumau-schenkn', 'Da klaane Maxi woit da Leararin heit sei Noosnmaumau schenkn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der kleine Maxi wollte der Lehrerin heute sein Nasenmaumau schenken!', '[{"kategorie": "wörtlich", "text": "\"Der kleine Maxi wollte großzügig sein und der Lehrerin heute seinen Nasenrammel schenken!\"  2. Der kleine Maxi, dieser Rotzbub, hat heute der Lehrerin stolz sein Nasenwutzelchen präsentiert!  3. Der kleine Maxi, dieser Schlingel, hat heute versucht, der Lehrerin seinen dreckigen Nasenpopel anzudrehen!"}]'::jsonb, ''),
  ('dea-brichd-si-de-finga-beim-noosnbuan', 'Dea brichd si de Finga beim Noosnbuan!', '', '', '', 'Echte Wiener Schmähperlen', 'Der bricht sich die Finger beim Nasenbohren!', '[{"kategorie": "wörtlich", "text": "\"Der bricht sich die Finger beim Nasenstieren!\"  2. \"Der verletzt sich sogar beim Nichtstun!\"  3. \"Der überanstrengt sich schon beim Faulenzen!\"  4. \"Dem bröselt der Arm ab, wenn er ''nen Lichtschalter betätigt!\"  5. \"Der bekommt ''nen Hexenschuss, wenn er nur ans ''Aufstehen'' denkt!\""}]'::jsonb, ''),
  ('dawaeu-mia-olle-hackln-is-bei-eam-wiida-noosnbuan-augsoogd', 'Dawäu mia olle hackln, is bei eam wiida Noosnbuan augsoogd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Derweil wir alle hackeln, ist bei ihm wieder Nasenbohren angesagt!', '[{"kategorie": "wörtlich", "text": "\"Während wir alle schuften, ist bei ihm wieder Nasenbohren angesagt!\"  2. Alle reißen sich den Arsch auf, nur einer ist wieder mal am Nichtstun !  3. Wir alle rackern uns die Seele aus dem Leib - nur dieser Nasenbohrer schaut bloß zu und sammelt wieder mal Pausen!"}]'::jsonb, ''),
  ('dea-brichd-si-de-finga-beim-noosnschdian', 'Dea brichd si de Finga beim Noosnschdian!', '', '', '', 'Echte Wiener Schmähperlen', 'Der bricht sich die Finger beim Nasenstieren!', '[{"kategorie": "wörtlich", "text": "\"Der bricht sich di9e Finger beim Nasenstochern!\"  2. \"Der verletzt sich sogar beim Nichtstun!\"  3. \"Der überanstrengt sich schon beim Faulenzen!\"  4. \"Dem bröselt der Arm ab, wenn er ''nen Lichtschalter betätigt!\"  5. \"Der bekommt ''nen Hexenschuss, wenn er nur ans ''Aufstehen'' denkt!\""}]'::jsonb, ''),
  ('dawaeu-mia-olle-hackln-is-bei-eam-wiida-noosnschdian-augsoogd', 'Dawäu mia olle hackln, is bei eam wiida Noosnschdian augsoogd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Derweil wir alle hackeln, ist bei ihm wieder Nasenstieren angesagt!', '[{"kategorie": "wörtlich", "text": "\"Während wir alle schuften, ist bei ihm wieder Nasenstochern angesagt!\"  2. Alle reißen sich den Arsch auf, nur einer ist wieder mal am Nichtstun !  3. Wir alle rackern uns die Seele aus dem Leib - nur dieser Nasenbohrer schaut bloß zu und sammelt wieder mal Pausen!"}]'::jsonb, ''),
  ('oone-sei-noosnfuada-kummda-in-da-frua-ned-ind-gaeng', 'Oone sei Noosnfuada kummda in da Frua ned ind Gäng!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ohne sein Nasenfutter kommt er in der Früh nicht in die Gänge!', '[{"kategorie": "wörtlich", "text": "\"Ohne eine Prise Schnupftabak kommt er morgens nicht in Schwung!\"  2. Er braucht erst eine Prise für die Nase, sonst läuft bei ihm morgens gar nichts!  3. Ohne Schnupf ist er morgens nicht zu gebrauchen!"}]'::jsonb, ''),
  ('wea-mit-an-noosngleckal-zum-dejt-kummd-schboad-si-es-zweite-traangl', 'Wea mit an Noosngleckal zum Dejt kummd, schboad si es zweite Traangl!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wer mit ''nem Nasenglöckerl zum Date erscheint, spart sich das zweite Trankl!', '[{"kategorie": "wörtlich", "text": "\"Wer mit ''nem Rotzglöckchen zum Date erscheint, spart sich das zweite Getränk!\"  2. Wer mit ''ner Rotzfahne zum Date kommt, zahlt nur eine Runde!  3. Ein Date mit Rotzglöckchen ist kein Date, das ist eine Ein-Mann-Ekel-Show - Getränke sind da rausgeschmissenes Geld!"}]'::jsonb, ''),
  ('schau-dem-haengd-a-fetts-rotzgleckal-aus-da-noosn-appetitlich-is-wos-aundas', 'Schau, dem hängd a fetts Rotzgleckal aus da Noosn - appetitlich is wos aundas!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Schau, dem hängt ein fettes Rotzglöckerl aus der Nase – appetitlich ist was anders!', '[{"kategorie": "wörtlich", "text": "\"Guck mal, dem hängt ein fetter Rotzpfopfen aus der Nase – gustiös ist was anders!\"  2. Siehst du das? Da pendelt ein glänzendes Rotzglöckchen unter seinem Nasenloch – appetitanregend ist was anders!  3. Dem baumelt ein ordentlicher Rotzfaden aus der Nase – da sag ich nur ''Mahlzeit''!\""}]'::jsonb, ''),
  ('gib-ocht-oida-dei-noosndrepfal-is-kuaz-davua-dass-da-in-kaffee-einefoid', 'Gib Ocht, Oida - dei Noosndrepfal is kuaz davua, dass da in Kaffee einefoid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Gib Acht, Alter - dein Nasentröpfchen ist kurz davor, dir in den Kaffee reinzufallen!', '[{"kategorie": "wörtlich", "text": "\"Pass auf, Mann – gleich landet dein Rotzglöckchen im Kaffee!\"  2. Ey, Bruder, Achtung! Dein Rotzpfropfen ist kurz davor, in deinen Kaffee zu plumpsen!  3. Vorsicht, Alter – dein Kaffee kriegt gleich extra Eiweiß, wenn der Rotzfaden aus deiner Nase drin landet!"}]'::jsonb, ''),
  ('dea-zaad-si-an-raummae-aus-da-noosn-und-pickd-eam-untad-tischplottn-so-a-schweiniigl', 'Dea zaad si an Raummä aus da Noosn und pickd eam untad Tischplottn - so a Schweiniigl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der zieht sich einen Rammel aus der Nase und pickt ihn unter die Tischplatte - so ein Schweinenigel!', '[{"kategorie": "wörtlich", "text": "\"Der fischt sich einen Nasenrammel aus der Rübe und klebt ihn unter die Tischplatte –  so ein Dreckschweinchen!\"  2. Der wühlt in der Nase und parkt den Popel unterm Tisch – einfach ekelhaft!  3. Der kratzt sich den Rotz aus''m Rüssel und schmiert ihn unter den Tisch – was für ein ungustiöser Rüpel!"}]'::jsonb, ''),
  ('fuenf-minuutn-ned-aufpassn-und-da-klaane-raummae-zaleegd-da-de-buudn', 'Fünf Minuutn ned aufpassn - und da klaane Raummä zaleegd da de Buudn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Fünf Minuten nicht aufpassen - und der kleine Rammel zerlegt dir die Bude!', '[{"kategorie": "wörtlich", "text": "\"Fünf Minuten unbeaufsichtigt - und der kleine Stöpsel zerlegt dir die Bude!\"  2. Eine Sekunde nicht hingeschaut – und der Knirps verwandelt die Wohnung in eine Nachkriegszone!  3. Fünf Minuten allein gelassen – und der kleine Racker baut dir die Bude ab bis auf die Grundmauern!"}]'::jsonb, ''),
  ('des-kost-di-kan-raummae', 'Des kost di kan Raummä!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das kostet dich keinen Rammel', '[{"kategorie": "wörtlich", "text": "\"Das kostet dich keinen Pappenstiel!\"  2. \"Das kostet dich fast nichts!\"  3. \"Das ist quasi geschenkt!\"  4. Das kostet dich einen [[Lercherlschas]]!"}]'::jsonb, ''),
  ('scheiss-di-ned-au-des-kost-di-kaa-raummal', 'Scheiss di ned au, des kost di kaa Raummal!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Scheiß dich nicht an, das kostet dich kein Rammelchen', '[{"kategorie": "wörtlich", "text": "\"Mach nicht in die Hose, das kostet dich keinen Pappenstiel!\"  2. \"Wieso zauderst du? Das kostet dich ja eh fast nichts!\"  3. \"Das ist quasi geschenkt - also quatsch nicht rum!\""}]'::jsonb, ''),
  ('ziag-in-finga-ausn-riassl-du-raummaeschdiira-du-varotzda', 'Ziag in Finga ausn Riassl, du Raummäschdiira, du varotzda!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Zieh den Finger aus dem Rüssel, du Rammelstierer, du verrotzter!', '[{"kategorie": "wörtlich", "text": "\"Zieh den Finger aus der Nase, du verrotzter Nasenbohrer!\"  2. \"Zieh den Griffel aus der Nase, du ekliger Popler!\"  3. Finger raus aus dem Zinken – wir sind hier nicht im Zoo!"}]'::jsonb, ''),
  ('des-is-kaa-fuassbolla-des-is-a-raummaeschdiira-dea-hod-mea-schdaundzeit-ois-boikontakt', 'Des is kaa Fuassbolla, des is a Raummäschdiira - dea hod mea Schdaundzeit ois Boikontakt!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Das ist kein Fußballer, das ist ein Rammelstierer - der hat mehr Standzeit als Ballkontakte!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Fußballer, das ist ein Nasenbohrer - der hat mehr Standzeit als Ballkontakte!\"  2. Das ist kein Fußballer, das ist ein Statist – der hat mehr Stehzeit als Aktionen!  3. Der ist kein Fußballer, das ist eine Rasen-Deko - der ballert nicht, der verwelkt!"}]'::jsonb, ''),
  ('du-varotzda-raummaeschdiira-du-oelaeaendicha', 'Du varotzda Raummäschdiira, du öläändicha!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du verrotzter Rammelkratzer, du elendiger!', '[{"kategorie": "wörtlich", "text": "\"Du verrotzter Nasenbohrer, du jämmerlicher!\"  2. \"Du versiffte Rotznase, du erbärmliche!\"  3. \"Du rotziger Flachwichser, du armseliger!\""}]'::jsonb, ''),
  ('ziag-in-finga-ausn-riassl-du-raummaekrotza-du-degutanta', 'Ziag in Finga ausn Riassl, du Raummäkrotza, du degutanta!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Zieh den Finger aus dem Rüssel, du Rammelkratzer, du degoutanter!', '[{"kategorie": "wörtlich", "text": "\"Zieh den Finger aus der Nase, du widerlicher Nasenbohrer!\"  2. \"Zieh den Griffel aus der Nase, du ekliger Popler!\"  3. Finger raus aus dem Zinken – wir sind hier nicht im Zoo, du ungustiöser Nasenbohrer!"}]'::jsonb, ''),
  ('da-neina-is-a-echta-raummaekrotza-mea-ois-sinnlos-umanaundschdee-und-lecha-ind-luft-schdiian-bringd-dea-ned-zsaumm', 'Da Neina is a echta Raummäkrotza - mea ois sinnlos umanaundschdee und Lecha ind Luft schdiian, bringd dea ned zsaumm!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Neuner ist ein echter Rammelkratzer - mehr als sinnlos herumstehen und Löcher in die Luft stieren, bringt der nicht zusammen!', '[{"kategorie": "wörtlich", "text": "\"Der Neuner ist kein Stürmer, das ist ein Nasenbohrer mit Rückennummer - mehr als sinnlos rumzustehen und Löcher in die Luft zu starren, bringt der nicht zusammen!\"  2. Der Neuner ist kein Goalgetter, das ist ein Nasenpopler - mehr als seinen Hintern plattzustehen und die Luft anzustarren, kriegt der nicht hin!  3. Dieser Nasenbohrer ist nutzlos fürs Team - mehr als Däumchen zu drehen und in die Gegend zu glotzen, bringt der nicht zustande!"}]'::jsonb, ''),
  ('a-klaans-raummal-is-kaa-problem-solaungs-no-ned-winkt', 'A klaans Raummal is kaa Problem - solaungs no ned winkt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein kleines Rammerl ist kein Problem - solange es noch nicht winkt!', '[{"kategorie": "wörtlich", "text": "\"Ein kleines Popelchen stört nicht weiter – außer, es macht Winke-Winke!\"  2. Ein kleines [[Nasenwutzerl]] fällt nicht auf, solange es nicht zu grüßen beginnt!  3. Ein bisschen Nasenrötzchen geht klar – erst wenn''s raushängt und zu winken beginnt, wird''s peinlich!"}]'::jsonb, ''),
  ('des-freche-raummal-is-so-klaa-wiara-biadeckl-fiad-owa-a-goschn-wiara-groossa', 'Des freche Raummal is so klaa wiara Biadeckl - fiad owa a Goschn wiara Groossa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das freche Rammerl ist so klein wie ein Bierdeckel - führt aber ''ne Gosch''n wie ein Großer!', '[{"kategorie": "wörtlich", "text": "\"Dieses Stöpselchen ist kaum größer als’n Bierdeckel, aber quatscht wie’n ausgewachsener Stammtischheld!\"  2. \"Der kleine Fratz ist so klein, dass er unter''m Tresen durchpasst – aber die Klappe größer als der Wirt!\"  3. Der kleine Racker ist kaum aus der Windel, hat aber schon ’ne Gosch''n wie ein Platzhirsch!"}]'::jsonb, ''),
  ('a-so-a-heazigs-raummal', 'A so a heazigs Raummal!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ein so ein herziges Rammerl', '[{"kategorie": "wörtlich", "text": "\"Was für ein liebes, süßes Kind!\"  2. \"Was für ein goldiges Kerlchen!\"  3. \"Das ist ja ein Zuckerl von einem Kind!\"  4. \"So ein liebes Wutzerl!\""}]'::jsonb, ''),
  ('a-so-a-goaschdigs-raummal', 'A so a goaschdigs Raummal!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein so ein garstiges Rammerl', '[{"kategorie": "wörtlich", "text": "\"Was für ein schlimmes Kind!\"  2. \"So ein ungezogenes Kerlchen!\"  3. \"Das ist ja ein Biest von einem Kind!\"  4. \"So ein garstiges Zwerglein!\""}]'::jsonb, ''),
  ('si-niidakiiwaen', 'si niidakiiwän', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich niederkübeln', '[{"kategorie": "wörtlich", "text": "\"sich niederkübeln\" (vom mittelhochdeutschen \"kübelen\"=\"kübeln\")"}, {"kategorie": "allg.", "text": "\"sich vollaufen lassen\" (kübelweise Alkohol in sich hineinschütten), sich zulöten, sich zuschütten, sich zuschweißen, sich zubetonieren"}]'::jsonb, 'si zuaschiidn'),
  ('oida-des-woa-ka-saufn-mea-des-woa-systematisches-niidakiiwaen', 'Oida, des woa ka Saufn mea, des woa systematisches Niidakiiwän!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Alter, das war kein Saufen mehr, das war systematisches Niederkübeln!', '[{"kategorie": "wörtlich", "text": "\"Alter, das war kein Saufen mehr, das war stumpf reinschütten ohne Ende!\"  2. Junge, das war kein Besäufnis, das war Selbstentkernung!  3. Alter, das war kein Saufen mehr, das war stumpfes Niede4rkübeln bis zur Selbstvernichtung!"}]'::jsonb, 'si niidakiiwän'),
  ('waunn-dea-amoi-aufaungd-head-a-easchd-wiida-auf-waunn-a-si-komplett-niidakiiwaed-hod', 'Waunn dea amoi aufaungd, head a easchd wiida auf, waunn a si komplett niidakiiwäd hod!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn der einmal anfängt, hört er erst wieder auf, wenn er sich komplett niedergekübelt hat!', '[{"kategorie": "wörtlich", "text": "\"Wenn der mal in Fahrt kommt, macht er erst wieder Schluss, wenn er sich komplett zugeschüttet hat!\"  2. Hat der erstmal angefangen, gibt’s nur noch Vollgas bis zur Selbstentkernung!  3. Wenn der mal anfängt, säuft er durch bis Ende Gelände - da ist der Totalabsturz vorprogrammiert!"}]'::jsonb, ''),
  ('a-ruabmzuuzla-mit-meinung-de-gefaealichste-suatn-mensch', 'A Ruabmzuuzla mit Meinung - de gefäalichste Suatn Mensch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein Rübenzuzler mit Meinung – die gefährlichste Sorte Mensch!', '[{"kategorie": "wörtlich", "text": "\"Ein Rübenlutscher mit Meinung – die gefährlichste Spezies Mensch!\"  2. Ein Hinterwäldler mit Sendungsbewusstsein – schlimmste Kombination!  3. Ein [[Dampfgescherter]], aber von sich selbst  restlos überzeugt – Alarmstufe Rot!"}]'::jsonb, ''),
  ('an-ruabmzuuzla-eakennsd-daraun-dass-a-beim-kreisvakea-easchd-amoi-deppad-schaut-und-noochdenkt', 'An Ruabmzuuzla eakennsd daraun, dass a beim Kreisvakea easchd amoi deppad schaut und noochdenkt!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Einen Rübenzuzler erkennst du daran, dass er beim Kreisverkehr erst einmal deppert schaut und nachdenkt!', '[{"kategorie": "wörtlich", "text": "\"Einen Burgenländer erkennst du daran, dass er beim Kreisverkehr erst einmal nachdenkt und blöd aus der Wäsche guckt!\"  2. Der Wiener hupt - derweil steht der Rübenzuzler vor''m Kreisverkehr und überlegt, ob er eh schon dran ist!  3. Einen Burgenländer erkennst du daran, dass er beim Kreisverkehr erst einmal stehenbleibt und blöd schaut!"}]'::jsonb, ''),
  ('groosse-goschn-nix-dahinta-a-echta-ruabmzuuzla-hoid', 'Groosse Goschn, nix dahinta - a echta Ruabmzuuzla hoid!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Große Gosch''n, nichts dahinter - ein echter Rübenzuzler halt!', '[{"kategorie": "wörtlich", "text": "\"Große Klappe, nichts dahinter - ein echter Rübenlutscher halt!\"  2. Viel Maul, null Eier - ein [[Dampfgescherter]] halt!  3. Große Klappe, weiche Knie - ein Provinzwappler halt!"}]'::jsonb, ''),
  ('dea-deppade-ruabmzuuzla-bringd-tofu-mit-und-soogd-dazua-grueueguut', 'Dea deppade Ruabmzuuzla bringd Tofu mit und soogd dazua ''Grüüguut''!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der depperte Rübenzuzler bringt Tofu mit und sagt dazu ‘Grillgut’!', '[{"kategorie": "wörtlich", "text": "\"Der verrückte Vegetarier bringt Tofu mit und nennt das ‘Grillgut’!\"  2. Der narrische Veggie-Typ bringt Sojablock mit und tut so, als wär’s BBQ!  3. Der durchgeknallte Fleischverweigerer legt Tofu auf den Rost und nennt das Essen!"}]'::jsonb, ''),
  ('friara-aansa-schaeaef-jetza-sacklpicka-so-rennds-in-da-galarii', 'Friara Aansa-Schääf, jetza Sacklpicka - so rennds in da Galarii!', '', '', '', 'Wiener Gaunersprache', 'Früher Einser-Chef, jetzt Sacklpicker - so rennt''s in der Galerie!', '[{"kategorie": "wörtlich", "text": "\"Früher Oberboss, jetzt Papiertütenkleber - das ist der Lauf der Dinge im Milieu!\"  2. Gestern Gangsterkönig, heute Leimtopf – so läuft’s im Verbrechermilieu!  3. Die Wiener Unterwelt frisst selbst die großen Bosse und spuckt sie als Sacklpicker wieder aus!"}]'::jsonb, ''),
  ('fria-woara-wea-jetzt-isa-sacklpicka', 'Fria woara wea - jetzt isa Sacklpicka!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher war er wer - jetzt ist er Sacklpicker!', '[{"kategorie": "wörtlich", "text": "\"Früher war er eine große Nummer - jetzt ist er Zuchthäusler und klebt Papiertüten!\"  2. Von ganz oben in der [[Galerie]] bis nach ganz unten – in die Papierütenfabrik!  3. Großes Tier war gestern, heut ist er Sacklpicker im [[Häf]]''n!"}]'::jsonb, ''),
  ('i-gee-ned-in-haeaefn-waeu-fias-sacklbickn-bin-i-ned-gmochd', 'I gee ned in Hääfn, wäu fias Sacklbickn bin I ned gmochd!', '', '', '', 'Wiener Gaunersprache', 'Ich gehe nicht in den Häfen, denn fürs Sackelpicken bin ich nicht gemacht!', '[{"kategorie": "wörtlich", "text": "\"Ich geh nicht ins Gefängnis, denn fürs Papiertütenkleben bin ich nicht gemacht!  2. \"Ich geh nicht ins Gefängnis, denn fürs Sacklpicken bin ich mir zu schade!\"  3. \"Knast? Nein danke - der Job als Tütenflicker liegt mir nicht!"}]'::jsonb, ''),
  ('dea-tuad-jetzt-sacklpickn-und-hod-ocht-joa-zeit-zum-noochdenkn', 'Dea tuad jetzt sacklpickn und hod ocht Joa Zeit zum Noochdenkn!', '', '', '', 'Wiener Gaunersprache', 'Der tut jetzt sacklpicken und hat acht Jahre Zeit zum Nachdenken!', '[{"kategorie": "wörtlich", "text": "\"Der klebt jetzt Papiertüten zusammen und hat acht Jahre Zeit zum Nachdenken!\"  2. \"Der sitzt jetzt am Leimtopf und hat acht Jahre Nachdenkpause!\"  3. Vom schnellen Leben zum langsamen Kleben – acht Jahre!"}]'::jsonb, ''),
  ('dea-schlawiina-rutscht-da-haeae-duachs-netz-wia-schmiiasaaf', 'Dea Schlawiina rutscht da Hää duachs Netz wia Schmiiasaaf!', '', '', '', 'Wiener Gaunersprache', 'Der Schlawiner rutscht der Höh durchs Netz wie Schmierseife!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Dieses ausgeschlafene Kerlchen rutscht der Polizei durchs Netz wie Schmierseife!\"  2. Dieser gerissene Gauner ist den Kieberern immer eine Nasenlänge voraus!  3. Dieser Strizzi geht durch Razzien wie andere durch ''ne offene Tür!"}]'::jsonb, ''),
  ('auf-unsara-schdiang-kennd-jeeda-den-oidn-schnaeaebrunza-dea-kummd-haam-und-pischd-ollawaeu-glei-in-busch-waeulas-auufe-bis-aufs-heisl-fost-nii-schoffd', 'Auf unsara Schdiang kennd jeeda den oidn Schnääbrunza - dea kummd haam und pischd ollawäu glei in Busch, wäulas auufe bis aufs Heisl fost nii schoffd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Auf unserer Stiege kennt jeder den alten Schneebrunzer - der kommt heim und pischt alleweil in den Busch, weil er es rauf bis zum Häusl nicht mehr schafft!', '[{"kategorie": "wörtlich", "text": "\"Bei uns im Haus kennt jeder den alten Inkontinenzler – kaum daheim, geht’s gleich ins Gebüsch, weil er’s nimmer bis hinauf zur Wohnung schafft!\"  2. \"Auf unserer Stiege kennt jeder den alten Schneebrunzer – kaum daheim, schifft er schon in den Busch, weil’s sich bis zum Häusl rauf nimmer ausgeht!\"  3. Wenn der senile Inkontinzenzler nach Hause kommt, erledigt er sein Geschäft meist gleich draußen im Freien, denn bis rauf ins Klo reicht die Zeit fast nie!"}]'::jsonb, ''),
  ('grooss-reedn-kaunn-a-owa-in-echt-isa-a-schnaeaebrunza', 'Grooss reedn kaunn a - owa in echt isa a Schnääbrunza!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Groß reden kann er - aber in echt ist er ein Schneebrunzer!', '[{"kategorie": "wörtlich", "text": "\"Im Reden ist er ein Held - aber im Machen ist er ein Schlappschwanz!\"  2. \"Große Klappe, nichts dahinter – ein echter Maulheld!\"  3. \"Viel Gelaber, null Eier - ein typischer Schaumschläger!\"  4. \"Viel Rauch um nichts – wenn der Qualm sich lichtet, steht da nur ein Warmduscher!\""}]'::jsonb, ''),
  ('in-unsara-maunnschoft-brauchma-oeoef-kriaga-aum-plotz-kaane-schnaeaebrunza', 'In unsara Maunnschoft brauchma ööf Kriaga aum Plotz, kaane Schnääbrunza!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'In unserer Mannschaft brauchen wir elf Krieger am Platz, keine Schneebrunzer!', '[{"kategorie": "wörtlich", "text": "\"In unserer Mannschaft brauchen wir elf Krieger am Platz, keine Warmduscher!\"  2. Am Platz brauchen wir Typen mit Biss, keine Eiertänzer!  3. Unsere Mannschaft braucht Mentalitätsspieler und keine Schönwetterfußballer!"}]'::jsonb, ''),
  ('olle-reedn-kaana-mocht-lauta-schnaeaebrunza', 'Olle reedn, kaana mocht - lauta Schnääbrunza!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Alle reden, keiner macht - lauter Schneebrunzer!', '[{"kategorie": "wörtlich", "text": "\"Reden tun sie alle, hackeln tut keiner - lauter Schaumschläger!\"  2. \"Große Worte, keine Taten – die ganze Belegschaft besteht nur aus Maulhelden und Drückebergern!\"  3. Hier wird nur diskutiert und delegiert - ein Paradies für Warmduscher und Sitzpinkler!"}]'::jsonb, ''),
  ('schnaeaebrunzatuum-is-de-modeane-foam-von-oaweidsvaweigarung-und-varauntwuatungsflucht', 'Schnääbrunzatuum is de modeane Foam von Oaweidsvaweigarung und Varauntwuatungsflucht!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Schneebrunzertum ist die moderne Form von Arbeitsverweigerung und Verantwortungsflucht!', '[{"kategorie": "wörtlich", "text": "\"Moderne Arbeitsverweigerung heißt nicht mehr Streik, sondern professionelles Schneebrunzertum: Verantwortung delegieren, eigene Anstrengung minimieren!\"  2. \"Neue Zeit, neue Ausreden: Schneebrunzertum ist die höfliche Revolte des Einzelnen gegen Anstrengung und Verantwortung!\"  3. \"Die Devise lautet nicht mehr ''Wer soll das machen?'', sondern ''Wie kann ich es nicht machen müssen?'' – das ist der Kern des modernen Drückebergertums!\""}]'::jsonb, ''),
  ('kumm-hea-du-siass-tschoppal-und-gib-da-uarli-oma-a-bussi', 'Kumm hea, du siass Tschoppal, und gib da Uarli-Oma a Bussi!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Komm her, du süßes Tschapperl, und gib der Urli-Oma ein Bussi!', '[{"kategorie": "wörtlich", "text": "\"Komm her, du süßes Schnuckelchen, und gib der Uroma einen Kuss!\"  2. \"Komm her, du kleiner Knuddelbär, und gib deiner Uroma ein Küsschen!\"  3. Komm her, du süßes Zwergerl, und gib der Urli-Oma ein dickes Bussi!"}]'::jsonb, ''),
  ('kumm-hea-du-siass-tschoppal-und-gib-in-uarli-opa-a-bussi', 'Kumm hea, du siass Tschoppal, und gib in Uarli-Opa a Bussi!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Komm her, du süßes Tschapperl, und gib dem Urli-Opa ein Bussi!', '[{"kategorie": "wörtlich", "text": "\"Komm her, du süßes Schnuckelchen, und gib dem Uropa einen Kuss!\"  2. \"Komm her, du kleiner Knuddelbär, und gib deinem Urgroßvater ein Küsschen!\"  3. Komm her, du süßes Zwergerl, und gib dem Urli-Opa ein dickes Bussi!"}]'::jsonb, ''),
  ('ma-kaunn-dem-tschoppal-ned-baeaes-sei-ea-maants-jo-guad-owa-ea-tschekd-hoid-nix', 'Ma kaunn dem Tschoppal ned bääs sei - ea maants jo guad, owa ea tschekd hoid nix!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Man kann dem Tschapperl nicht böse sein - er meint''s ja gut, aber er checkt halt nichts!', '[{"kategorie": "wörtlich", "text": "\"Man kann dem armen Würstel nicht böse sein - er meint''s ja gut, aber er checkt halt nichts!\"  2. Man kann dem [[Dillo]] nichts übelnehmen - sein Herz ist am rechten Fleck, nur leider nicht sein Kopf!  3. Dem armen Wirrkopf darfst net gram sein – der Wille is da, nur der Durchblick fehlt ihm!"}]'::jsonb, ''),
  ('des-tschoppal-hod-ka-aunung-wo-s-launggeed', 'Des Tschoppal hod ka Aunung, wo''s launggeed!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Tschapperl hat keine Ahnung, wo''s langgeht!', '[{"kategorie": "wörtlich", "text": "\"Das arme Würstel blickt überhaupt nicht durch!\"  2. Der Kindskopf steht da und schaut, kriegt aber nichts mit!\"  3. Der arme [[Tropf]] weiß weder ein noch aus!  3. Der [[Dillo]] hat überhaupt keinen Plan!"}]'::jsonb, ''),
  ('heast-du-klaans-tschoppal-meak-da-aans-wea-zliab-is-bleibd-liing', 'Heast, du klaans Tschoppal, meak da aans: Wea zliab is, bleibd liing!', '', '', '', 'Wiener Gaunersprache', 'Hör mal, du kleines Tschapperl, merke dir eines: Wer zu lieb ist, bleibt liegen!', '[{"kategorie": "wörtlich", "text": "\"Hör mal, du kleiner Kindskopf, merk dir eins: Wer zu lieb ist, bleibt liegen!\"  2. \"Hör zu, du kleiner Dummkopf, vergiss nie: Wer nur nett ist, kommt unter die Räder!\"  3. Hör mal, du Grünschnabel: Zu lieb sein heißt verlieren!"}]'::jsonb, ''),
  ('heia-is-da-tschoppalsolood-friara-gwochsn-waeu-da-winta-so-mueued-woa', 'Heia is da Tschoppalsolood friara gwochsn, wäu da Winta so müüd woa!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Heuer ist der Tschapperlsalat früher gewachsen, weil der Winter so mild war!', '[{"kategorie": "wörtlich", "text": "\"Heuer ist der Jungsalat noch früher gewachsen, weil der Winter so mild war!\"  2. Der Feldsalat ist dieses Jahr noch früher dran, weil es im Winter keinen richtigen Frost gegeben hat!  3. Durch den milden Winter sprießt der erste Frühlingssalat in diesem Jahr besonders zeitig!"}]'::jsonb, ''),
  ('da-tschoppalschbaagl-is-a-jeeds-joa-wos-gaunz-bsundas-waeura-da-easchde-schbaagl-im-frueuejoa-is', 'Da Tschoppalschbaagl is a jeeds Joa wos gaunz Bsundas, wäura da easchde Schbaagl im Früüjoa is!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Der Tschapperlspargel ist jedes Jahr etwas ganz Besonderes, weil er der erste Spargel im Frühjahr ist!', '[{"kategorie": "wörtlich", "text": "\"Der Jungspargel vom allerersten Stichist jedes Jahr etwas ganz Besonderes, weil er der erste Spargel im Frühjahr ist!\"  2. Kulinarisch gesehen ist der Frühspargel die zarteste und edelste Form des Spargelgenusses - eben weil er der Erste ist!  3. Für Spargelfans ist der Tschapperlspargel kein Gemüse, sondern ein religiöses Erlebnis – die Auferstehung aus der Erde!"}]'::jsonb, ''),
  ('wea-freiwuellich-tschoppalwossa-saufd-hod-entweeda-diinst-ooda-an-fueueraschein', 'Wea freiwüllich Tschoppalwossa saufd, hod entweeda Diinst ooda an Füüraschein!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wer freiwillig Tschapperlwasser säuft, hat entweder Dienst oder an Führerschein!', '[{"kategorie": "wörtlich", "text": "\"Wer freiwillig alkoholfreie Limonade trinkt, hat entweder Dienst oder einen Führerschein!\"  2. Wenn jemand freiwillig zur alkoholfreien Brause greift, ist er entweder im Dienst oder will den Schein behalten!  3. Freiwillig ohne Alkohol? Entweder Hackler im Einsatz oder Angst vorm Alkotest!"}]'::jsonb, ''),
  ('dea-ungustl-haed-si-aane-ind-pappn-vadiint', 'Dea Ungustl häd si aane ind Pappn vadiint!', '', '', '', 'Wiener Gaunersprache', 'Der Ungustl hätte sich eine in die Pappen verdient!', '[{"kategorie": "wörtlich", "text": "\"Dieser Unsympathler hätte sich eine aufs Maul verdient!\"  2. \"Diesem Widerling gehört einmal ordentlich die Gosch''n poliert!\"  3. \"Diesem Stinkstiefel sollte man mal die Fresse polieren!\""}]'::jsonb, ''),
  ('sei-kaa-soicha-ungustl-oida', 'Sei kaa soicha Ungustl, Oida!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Sei kein solcher Ungustl, Alter!', '[{"kategorie": "wörtlich", "text": "\"Sei nicht so ungut, Alter!\"  2. \"Hör auf, so giftig herumzugranteln, Alter!\"  3. \"Alter, reiß dich zusammen und sei nicht so ein Stinkstiefel!\""}]'::jsonb, ''),
  ('da-pforra-hod-friara-vuam-zipfalreissa-losta-gwoant-gmaand-woa-de-soebstbefriidigung-kiachlich-umschriebm', 'Da Pforra hod friara vuam Zipfalreissa-Losta gwoant - gmaand woa de Söbstbefriidigung, kiachlich umschriebm!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Der Pfarrer hat früher vor dem ''Zipferlreißer-Laster'' gewarnt – gemeint war die Selbstbefriedigung, kirchlich umschrieben!', '[{"kategorie": "wörtlich", "text": "\"Früher wurde von der Kanzel vor dem „Zipferlreißer-Laster“ gewarnt, also vor der Selbstbefriedigung, kirchlich umschrieben!\"  2. In Predigten galt das „Zipferlreißer-Laster“ als schwere Sünde – gemeint war damit die Selbstbefriedigung, religiös verklausuliert!  3. Mit dem Ausdruck „Zipferlreißer-Laster“ meinte der Pfarrer einst die Selbstbefriedigung - theologisch formuliert!"}]'::jsonb, ''),
  ('du-grindiga-oaschwoama-zipfalreissa', 'Du grindiga, oaschwoama Zipfalreissa!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du grindiger, arschwarmer Zipferlreißer!', '[{"kategorie": "wörtlich", "text": "\"Du schmuddeliger, widerlicher Wichser!\"  2. \"Du grindiger, verkommener Dreckskerl!\"  3. \"Du widerliches, schmieriges Arschloch!\""}]'::jsonb, ''),
  ('reed-mas-in-a-sackal-und-haeng-mas-aun-de-tia', 'Reed mas in a Sackal und häng mas aun de Tia!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Rede es mir in ein Sackerl und hänge es mir an die Tür!', '[{"kategorie": "wörtlich", "text": "\"Ergieße deinen Redefluss in eine Plastiktüte und häng sie mir dann zum Späteranhören an die Tür!\" (scherzhaft für): \"Dein Geschwafel interessiert mich nicht ein bisschen!\"  3. \"Spar dir dein Geschwafel!\""}]'::jsonb, ''),
  ('reeds-in-a-plastiksackal', 'Reeds in a Plastiksackal!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Sprich alles in ein Plastiksackerl!', '[{"kategorie": "wörtlich", "text": "\"Ergieße deinen Redefluss in ein Plastiksackerl!\"  2. (scherzhaft für): Dein Geschwafel interessiert mich nicht im Geringsten!  3. Spar dir dein Geschwafel!"}]'::jsonb, ''),
  ('gee-host-a-plastiksackl-fia-meine-gummischdiifaen-i-wueue-ma-in-koffaraum-ned-wiida-voisaandln', 'Gee, host a Plastiksackl fia meine Gummischdiifän? I wüü ma in Koffaraum ned wiida voisaandln!', '', '', '', 'Wiener Mechaniker-Slang', 'Geh, hast du ein Plastiksackl für meine Gummistiefel? I will mir den den Kofferraum nicht wieder vollsandeln!', '[{"kategorie": "wörtlich", "text": "\"Hast du eine Plastiktüte für meine Gummistiefel? Ich will mir den Kofferraum nicht wieder einsauen!\"  2. \"Hast du ein Plastiksackl für meine Gatschstiefel - sonst saue ich mir das Auto wieder komplett ein!\"  3. \"Ich brauche eine Plastiktüte, sonst habe ich nachher den ganzen Kofferraum wieder voller Dreck!\""}]'::jsonb, ''),
  ('des-is-so-a-krischpindl-den-kenntasd-in-an-feichtn-papiasackl-wegtroong', 'Des is so a Krischpindl - den kenntasd in an feichtn Papiasackl wegtroong!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist so ein Krischpindl - den könntest du in einem feuchten Papiersackl wegtragen!', '[{"kategorie": "wörtlich", "text": "\"Das ist so eine halbe Portion - den könntest du in einer feuchten Papiertüte wegtragen!\"   2. Der ist so schmächtig - den kannst du in eine feuchte Papiertragtasche packen!  3. Der ist ein solches Leichtgewicht - den kannst du mit zwei Fingern zusammenfalten und in einer Papiertüte wegtragen!"}]'::jsonb, ''),
  ('schdeck-ma-s-wiaschdl-in-a-papiasackal-sunst-pick-i-noocha-wiara-fliangfaunga', 'Schdeck ma s''Wiaschdl in a Papiasackal - sunst pick I noocha wiara Fliangfaunga!', '', '', '', 'Wiener Würstelstandjargon', 'Steck mir das Würschtl in ein Papiersackerl - sonst pick'' ich nachher wie ein Fliegenfänger!', '[{"kategorie": "wörtlich", "text": "\"Pack mir das Würstel in ''ne Papiertüte - sonst klebe ich nachher wie ein Fliegenstreifen!\"  2. Steck mir das Würstel ins Papiersackerl, sonst werd ich noch zur wandelnden Fettfalle!  3. Gib mir die Würstel in eine Papiertragtasche - sonst pick ich nachher wie ''ne Sau!"}]'::jsonb, ''),
  ('des-neilonsackal-kaunnsd-da-schboan-do-rinnd-ma-de-gaunze-baatz-iwaroi-hii', 'Des Neilonsackal kaunnsd da schboan - do rinnd ma de gaunze Baatz iwaroi hii!', '', '', '', 'Wiener Würstelstandjargon', 'Das Nylonsackerl kannst du dir sparen - da rinnt mir die ganze Batz überall hin!', '[{"kategorie": "wörtlich", "text": "\"Vergiss das Nylonsackerl - da läuft mir die Sauce überall rein!\"  2. Dieses billige Plastiksackerl kannst du behalten – da geht das Zeug unten gleich wieder raus!  3. Nylonsackerl bringt nichts – da rinnt die ganze Brühe durch!"}]'::jsonb, ''),
  ('a-guads-neilosackl-muass-zwaa-sochn-kenna-daumpfn-lossn-damits-brood-ned-aufwaachd-und-gleichzeitich-dicht-sei-damit-de-baaz-ned-ausrinnd', 'A guads Neilosackl muass zwaa Sochn kenna: daumpfn lossn, damits Brood ned aufwaachd, und gleichzeitich dicht sei, damit de Baaz ned ausrinnd!', '', '', '', 'Wiener Würstelstandjargon', 'Ein gutes Nylonsackl muss zwei Sachen können: dampfen lassen, damit das Brot nicht aufweicht, und gleichzeitig dicht sein, damit die Batz nicht ausrinnt!', '[{"kategorie": "wörtlich", "text": "\"Eine gute Plastiktüte muss zweierlei können: dampfen lassen, damit das Brot nicht aufweicht, und gleichzeitig dicht sein, damit die Sauce nicht ausrinnt!\"  2. \"Ein gutes Nylonsackerl muss zwei Anforderungen erfüllen: Es soll Dampf entweichen lassen, damit das Brot nicht weich wird, und zugleich dicht sein, damit keine Sauce ausläuft!\"  3. \"Ein gutes Nylonsackl muss dampfdurchlässig sein, um das Aufweichen des Brots zu verhindern, und gleichzeitig flüssigkeitsundurchlässig, um das Auslaufen der Sauce zu vermeiden!\""}]'::jsonb, ''),
  ('sackal-fias-gackal', 'Sackal fias Gackal', 'das', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sackerl fürs Gackerl', '[{"kategorie": "wörtlich", "text": "\"Kacktüte für Hunde\""}, {"kategorie": "", "text": "\"Plastikbeutel für den Hundekot\""}, {"kategorie": "", "text": "\"Sammeltüte für Hundehinterlassenschaften\""}]'::jsonb, 'I gee Gassi wia aundare zua Schicht - mit an Sackal fias Gackal und null Loon!'),
  ('pocks-gscheid-ei-sunst-hob-i-den-gaunzn-schaas-im-sackl', 'Pocks gscheid ei - sunst hob I den gaunzn Schaas im Sackl!', '', '', '', 'Wiener Würstelstandjargon', 'Pack’s g''scheit ein - sonst hab ich den ganzen Schas im Sackerl!', '[{"kategorie": "wörtlich", "text": "\"Pack’s ordentlich ein - sonst hab ich das ganze Zeug im Sackl!\"  2. \"Pack es transportsicher ein, sonst landet der ganze Inhalt im Beutel!\"  3. \"Bitte richtig einpacken, sonst läuft alles in den Plastikbeutel aus!\""}]'::jsonb, ''),
  ('s-letzte-heemad-hod-kaane-sackln', 's letzte Heemad hod kaane Sackln!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Das letzte Hemd hat keine Sackeln!', '[{"kategorie": "wörtlich", "text": "Das letzte Hemd hat keine Taschen!  2. (fig.) Ins Grab kann man sein Geld nicht mitnehmen!  3. Nackt kommst du auf die Welt, nackt gehst du wieder!"}]'::jsonb, ''),
  ('in-sein-neichn-sackl-schauda-richtig-faesch-aus', 'In sein neichn Sackl schauda richtig fäsch aus!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'In seinem neuen Sackel sieht er richtig fesch aus!', '[{"kategorie": "wörtlich", "text": "\"In seinem neuen Sakko sieht er richtig schick aus!\"  2. (allg.) Sein neues Sakko steht ihm richtig gut!  3. In seinem neuen Sakko macht er eine richtig tolle Figur!"}]'::jsonb, ''),
  ('heid-hau-i-mi-ins-sackl', 'Heid hau I mi ins Sackl!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Heute haue ich mich ins Sackel!', '[{"kategorie": "wörtlich", "text": "\"Heute werf'' ich mein Sakko über!\"  2. (scherzhaft für): Heute werfe ich mich in Schale!  3. Heute lege ich meinen besten Zwirn an!"}]'::jsonb, ''),
  ('waunn-mi-mei-sackl-juckd-kummd-a-schlechds-weeda', 'Waunn mi mei Sackl juckd, kummd a schlechds Weeda!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn mich mein Sackl juckt, kommt schlechtes Wetter!', '[{"kategorie": "wörtlich", "text": "\"Wenn es mich am Hodensack juckt, kommt schlechtes Wetter!\"  2. \"Juckt der Sack, wird das Wetter schlecht!\"  3. \"Juckts im Schritt, bleibt''s Wetter nicht fit!\""}]'::jsonb, ''),
  ('dea-liigd-ned-oone-grund-so-a-sacklschbitz-tuad-waeae', 'Dea liigd ned oone Grund - so a Sacklschbitz tuad wää!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der liegt nicht ohne Grund – so ein Sacklspitz tut weh!', '[{"kategorie": "wörtlich", "text": "\"Der bleibt nicht zum Spaß liegen - so ein Tritt ins Gemächt tut richtig weh!\"  2. \"Klar kann er nicht mehr – so ein Spitz in die Familienjuwelen macht jeden kampfunfähig!\"  3. \"Ein Sacklspitz ist kein Zuckerschlecken - damit versetzt du jeden Mann in die Embryonalstellung!\""}]'::jsonb, ''),
  ('a-schwaumm-wochsd-nua-duat-wo-da-boodn-de-feichtigkeit-und-da-baumpartna-zsaummpassn', 'A Schwaumm wochsd nua duat, wo da Boodn, de Feichtigkeit und da Baumpartna zsaummpassn!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Ein Schwamm wächst nur dort, wo Boden, Feuchtigkeit und Baumpartner zusammenpassen!', '[{"kategorie": "wörtlich", "text": "\"Schwämme wachsen ausschließlich in Lebensräumen, in denen Boden, Wasserhaushalt und Wirtsbaum zusammenpassen!\"  2. \"Ohne den richtigen Boden, genug Feuchtigkeit und den passenden Baum wächst kein Schwamm!\"  3. \"Schwämme sind standortgebunden und benötigen spezifische Boden- und Feuchtigkeitsbedingungen sowie passende Baumpartner!\""}]'::jsonb, ''),
  ('min-waachn-schwaumm-geeds-owa-da-hoate-reissd-da-de-haut-auf', 'Min waachn Schwaumm geeds, owa da hoate reissd da de Haut auf!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit dem weichen Schwamm geht’s, aber der harte reißt dir die Haut auf!', '[{"kategorie": "wörtlich", "text": "\"Der weiche Schwamm passt, aber der harte scheuert dir die Haut runter!\"  2. \"Der weiche Schwamm eignet sich zum Waschen, aber mit dem harten schrubbst du dir die Haut kaputt!\"  3. \"Fürs Gesicht nimm lieber den weichen Schwamm - der kratzige schmirgelt dir sonst die Haut ab!\""}]'::jsonb, ''),
  ('a-schbitzal-a-schwipsal-a-reischal-a-schwaumm-is-unsa-taegliches-oaweitsprogramm', 'A Schbitzal, a Schwipsal, a Reischal, a Schwaumm is unsa tägliches Oaweitsprogramm!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Spitzerl, ein Schwipserl, ein Räuscherl, ein Schwamm ist unser tägliches Arbeitsprogramm!', '[{"kategorie": "wörtlich, Scherzreim der Gewohnheitsrinker", "text": "\"Ein Spitz, ein Schwips, ein Rausch, ein [[Schwamm]] - das ist unser tägliches Trinkprogramm!\"  2. \"A Glaserl zum Start und a Rauscherl zum Schluss – des is unser Tagesprogramm, Punkt und Schluss!\"  3. \"Ein Spitzerl, ein Schwipserl, ein Rauscherl dabei – so bleibt man den ganzen Tag standfest und frei!\""}]'::jsonb, ''),
  ('a-schbitzal-in-da-frua-ghead-bei-uns-zua-grundausschdottung', 'A Schbitzal in da Frua ghead bei uns zua Grundausschdottung!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Spitzerl in der Früh gehört bei uns zur Grundausstattung!', '[{"kategorie": "wörtlich", "text": "\"Ein Schwipserl am Morgen ist bei uns Pflicht!\"  2. \"Ohne Grundpegel in der Früh geht bei uns gar nichts!\"  3. \"Ein kleines Räuschlein am Morgen vertreibt Kummer und Sorgen!\""}]'::jsonb, ''),
  ('des-is-a-keazlschlicka-dea-iwaroi-nua-suende-wittad', 'Des is a Keazlschlicka, dea iwaroi nua Sünde wittad!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Das ist ein Kerzerlschlucker, der überall nur Sünde wittert!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Moralapostel, der in jedem Spaß gleich Sünde sieht!\"  2. \"Das ist ein selbstgerechter Frömmler, der überall moralischen Verfall wittert!\"  3. \"Das ist ein Sittenwächter, der nichts anderes kann als Sünde riechen!\""}]'::jsonb, ''),
  ('des-keazlweib-rennd-in-gaunzn-toog-min-beetbiachl-und-in-roosnkraunz-umanaund-de-waass-gaunz-genau-wea-aum-suundoog-ned-in-da-kichan-woa', 'Des Keazlweib rennd in gaunzn Toog min Beetbiachl und in Roosnkraunz umanaund - de waass gaunz genau, wea aum Suundoog ned in da Kichan woa!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Das Kerzerlweib rennt den ganzen Tag mit''m Betbüchl und dem Rosenkranz herum - die weiß ganz genau, wer am Sonntag nicht in der Kirche war!', '[{"kategorie": "wörtlich", "text": "\"Diese selbstgerechte Frömmlerin läuft den ganzen Tag mit Gebetbuch und Rosenkranz herum und weiß ganz genau, wer sonntags nicht in der Kirche war!\"  2. \"Sie gilt als notorische Kirchgängerin – mit Rosenkranz in der Hand und ständigem Blick darauf, wer in der Sonntagsmesse fehlt!\"  3. \"Die Alte ist eine frömmelnde Moralwächterin, die mit Gebetbuch und Rosenkranz patrouilliert und Buch über Kirchgänger führt!\""}]'::jsonb, ''),
  ('du-gheast-ausgschissn-und-weggschmissn', 'Du gheast ausgschissn und weggschmissn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du gehörst ausgeschissen und weggeschmissen!', '[{"kategorie": "wörtlich", "text": "\"Du bist menschlicher Müll und gehörst entsorgt!\"  2. \"Du bist ein Haufen Scheiße - für dich gibt’s nur noch die Tonne!\"  3. \"Du bist das Allerletzte - dich kann man nur ausscheißen und wegschmeißen!\""}]'::jsonb, ''),
  ('do-geed-an-zgleich-da-oasch-zua-unds-maeu-auf', 'Do geed an zgleich da Oasch zua unds Mäu auf!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da geht einem zugleich der Arsch zu und das Maul auf!', '[{"kategorie": "wörtlich", "text": "\"Da geht dir zeitgleich das Maul auf und der Arsch auf Grundeis!\"  2. \"Da bleibt dir die Luft weg, und die Kinnlade klappt dir gleichzeitig runter!\"  3. \"Da bleibt dir die Spucke weg, und gleichzeitig friert dir das Blut ein!\""}]'::jsonb, ''),
  ('ma-kaunn-da-nix-vuaweafn-aussa-dassd-intellektuell-a-voipfostn-bist', 'Ma kaunn da nix vuaweafn - aussa dassd intellektuell a Voipfostn bist!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Man kann dir nichts vorwerfen – außer dass du intellektuell ein Vollpfosten bist!', '[{"kategorie": "wörtlich", "text": "\"Man kann dir nichts ankreiden - außer dass du ein unterbelichteter Volldillo bist!\"  2. \"Man findet an dir nichts auszusetzen - bis man dich denken hört!\"  3. \"Dir ist konkret nichts anzulasten – außer dass du ein hirnamputierter Vollkoffer bist!\""}]'::jsonb, ''),
  ('nuara-absoluta-voidillo-kummd-auf-so-a-saudumme-idaeae', 'Nuara absoluta Voidillo kummd auf so a saudumme Idää!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nur ein absoluter Volldillo kommt auf so eine saudumme Idee!', '[{"kategorie": "wörtlich", "text": "\"Auf so eine saudumme Idee kommt wirklich nur ein absoluter Vollpfosten!\"  2. \"So was denkt sich nur ein hirnverbrannter Vollidiot aus!\"  3. \"Auf so was kommt nur ein komplett unterbelichteter Volldepp!\""}]'::jsonb, ''),
  ('wos-woadn-des-bitte-fiara-aktion-du-voikoffa', 'Wos woadn des bitte fiara Aktion, du Voikoffa?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was war denn das bitte für eine Aktion, du Vollkoffer?', '[{"kategorie": "wörtlich", "text": "\"Was zur Hölle war das denn für eine Aktion, du Vollpfosten?\"  2. \"Was war das bitte für ein Scheiß, du Volldepp?\"  3. \"Was sollte dieser Mist jetzt gerade, du Volldillo?\""}]'::jsonb, ''),
  ('ma-froogd-si-echt-wia-so-a-voipoidl-biagamaasta-wean-kau', 'Ma froogd si echt, wia so a Voipoidl Biagamaasta wean kau!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Man fragt sich echt, wie so ein Vollpoldl Bürgermeister werden kann!', '[{"kategorie": "wörtlich", "text": "\"Man fragt sich echt, wie so ein Vollpfosten Bürgermeister werden kann!\"  2. \"Es ist mir ein Rätsel, wie es so ein Volldillo an die Spitze der Stadt schaffen kann!\"  3. \"Wie kann so ein Vollkoffer bitte ins Bürgermeisteramt rutschen?\""}]'::jsonb, ''),
  ('du-hianamputiiada-voipoidl', 'Du hianamputiiada Voipoidl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du hirnamputierter Vollpoidl!', '[{"kategorie": "wörtlich", "text": "\"Du hirnamputierter Vollpfosten!\"  2. \"Du geistig umnachteter Volldillo!\"  3. (Deutschland): \"Du strunzdummer Vollhorst!\""}]'::jsonb, ''),
  ('schiiri-schiiri-hea-moi-zua-blind-wia-nii-voidepp-du', 'Schiiri, Schiiri, hea moi zua: Blind wia nii, Voidepp du!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Schiri, Schiri, hör mal zu: Blind wie nie, Volldepp du!', '[{"kategorie": "wörtlich, Reim/Chant aus dem Ultra-Fanblock", "text": "\"Schiri, Schiri, hör mal zu: blind gepfiffen, Vollweh du!\"  2. \"Schiri, Schiri, Überblick? – Fehlanzeige, Vollhorst-Blick!\"  3. \"Schiri, Schiri, blind gepfiffen - so ein Volldepp g''hört zerrissen!\""}]'::jsonb, ''),
  ('maunchmoi-fueue-i-mi-wiara-voitrottl-waunn-i-aun-meine-fuemf-ex-n-zruckdenk', 'Maunchmoi füü I mi wiara Voitrottl, waunn I aun meine fümf Ex''n zruckdenk!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Manchmal fühle ich mich wie ein Volltrottel, wenn ich an meine fünf ''Ex-en'' zurückdenke!', '[{"kategorie": "wörtlich", "text": "\"Manchmal komm ich mir vor wie ein Vollidiot, wenn ich an meine fünf Ex-Frauen zurückdenke!\"  2. \"Rückblickend frage ich mich, wie ich Volldepp fünfmal in dieselbe Ehefalle laufen konnte!\"  3. \"Manchmal fühl ich mich wie ein unbelehrbarer Vollpfosten, wenn ich die Bilder meiner fünf Ex-Frauen sehe!\""}]'::jsonb, ''),
  ('da-gooli-dea-schittla-hod-heit-sei-hian-im-schbind-lossn', 'Da Gooli, dea Schittla, hod heit sei Hian im Schbind lossn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Goalie, dieser Schüttler, hat heute sein Hirn im Spind gelassen!', '[{"kategorie": "wörtlich", "text": "\"Der Torwart, dieser Idiot, muss heute sein Hirn beim Umziehen in der Kabine vergessen haben!\"  2. Der Keeper, dieser Vollwappler, steht im Tor wie ein Orientierungsloser ohne Hirn!  3. Der Keeper ist heute geistig komplett abwesend - klassischer Schüttler im Kasten!"}]'::jsonb, ''),
  ('mit-so-an-voischittla-in-da-partii-wiad-a-jeeda-bruch-zua-lottarii', 'Mit so an Voischittla in da Partii wiad a jeeda Bruch zua Lottarii!', '', '', '', 'Wiener Gaunersprache', 'Mit so ’nem Vollschüttler in der Partie wird jeder Bruch zur Lotterie!', '[{"kategorie": "wörtlich", "text": "\"Mit so ’nem Volltrottel im Team wird jeder Coup zur Lotterie!\"  2. \"Wer so einen Dillo in die Gang aufnimmt, macht jeden Job zum reinen Glücksspiel!\"  3. \"Seit dieser Vollpfosten zur Bande gehört, fühlt sich jeder Einbruch wie russisches Roulette an!\""}]'::jsonb, ''),
  ('dea-schaut-aus-wiara-schdaapueuez-owa-bei-schwammaln-bin-i-imma-haaglich', 'Dea schaut aus wiara Schdaapüüz - owa bei Schwammaln bin I imma haaglich!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der schaut aus wie ein Steinpilz - aber bei Schwammerln bin ich immer heikel!', '[{"kategorie": "wörtlich", "text": "\"Der sieht zwar aus wie ein Steinpilz, aber bei Pilzen bin ich immer vorsichtig!\"  2. \"Könnte ein Steinpilz sein, aber ich geh bei Schwammerln lieber auf Nummer sicher!\"  3. \"Optisch erinnert er an einen Steinpilz, doch bei Pilzen ist stets Vorsicht geboten!\""}]'::jsonb, ''),
  ('waunnsd-deine-taepf-und-reindln-ned-zakrotzn-wueuesd-muassd-a-waachares-schwammal-zum-putzn-neema', 'Waunnsd deine Täpf und Reindln ned zakrotzn wüüsd, muassd a waachares Schwammal zum Putzn neema!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn du deine Töpfe und Reindln nicht zerkratzen willst, musst du ein weicheres Schwammerl zum Putzen nehmen!', '[{"kategorie": "wörtlich", "text": "\"Wenn du deine Töpfe und Pfannen schonen willst, solltest du ein weicheres Schwämmchen verwenden!\"  2. \"Um Kratzer zu vermeiden, nimm lieber ein weiches Schwämmchen zum Putzen der Töpfe und Pfannen!\"  3. \"Wenn dir deine Töpfe und Pfannen lieb sind, greif lieber zu einem weicheren Schwämmchen - die harten hinterlassen Kratzer!\""}]'::jsonb, ''),
  ('mei-oide-hod-schoo-noch-zwaa-aachtaln-ia-schwammal-i-sauf-daunn-in-rest-vom-doppla-aus-damit-ma-peeglmaeaesich-wiida-auf-gleicha-haeae-san', 'Mei Oide hod schoo noch zwaa Aachtaln ia Schwammal - I sauf daunn in Rest vom Doppla aus, damit ma peeglmääsich wiida auf gleicha Hää san!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Meine Alte hat schon nach zwei Achterln ihr Schwammerl - ich sauf dann den Rest vom Doppler aus, damit wir pegelmäßig wieder auf gleicher Höhe sind!', '[{"kategorie": "wörtlich", "text": "\"Meine Frau hat schon nach zwei Achterln ihr kleines Schwipserl – also zieh ich den Rest vom Doppler leer, damit wir pegelmäßig wieder auf Augenhöhe sind!\"  2. \"Meiner Alten reichen zwei Achterln für ein kleines [[Spitzerl]] - ich erledige dann den Rest vom Doppler, damit wir wieder synchron sind!\"  3. \"Meine Frau hat schon nach zwei Achterln ihr Schwammerl - ich saug dann den Rest vom Doppler aus, damit wir auf derselben Wellenlänge diskutieren!\""}]'::jsonb, ''),
  ('ea-is-aeae-liab-owa-hoit-a-bissl-a-schwammal', 'Ea is ää liab - owa hoit a bissl a Schwammal!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Er ist eh lieb, aber halt ein bisschen ein Schwammerl!', '[{"kategorie": "wörtlich", "text": "\"Er ist ja eh nett, aber leider ein bisschen ein Dussel!\"  2. \"Er ist ja ganz nett, aber irgendwie auch ein Schütti!\"  3. \"Er ist ja ein lieber Kerl, aber ein wenig neben der Spur - ein kleiner Dillo halt!\""}]'::jsonb, ''),
  ('aufs-schwammal-schdeing', 'aufs Schwammal schdeing', '', '', '', 'Wiener Mechaniker-Slang', 'aufs Schwammerl steigen', '[{"kategorie": "wörtlich, Mechanikerjargon", "text": "\"aufs Gas steigen\""}, {"kategorie": "", "text": "\"das Gaspedal durchtreten\""}, {"kategorie": "", "text": "\"Stoff geben\""}, {"kategorie": "", "text": "\"Vollgas geben\""}]'::jsonb, 'Waunnsd iwahoin wüüsd, muassd a bissl aufs Schwammal schdeing!'),
  ('waunnsd-iwahoin-wueuesd-muassd-a-bissl-aufs-schwammal-schdeing', 'Waunnsd iwahoin wüüsd, muassd a bissl aufs Schwammal schdeing!', '', '', '', 'Wiener Mechaniker-Slang', 'Wennst überholen willst, musst ein bisschen aufs Schwammerl steigen!', '[{"kategorie": "wörtlich", "text": "\"Wenn du überholen willst, musst du kräftig aufs Gaspedal treten!\"  2. \"Du musst mal fest Gas geben, sonst wird''s nichts mit Überholen!\"  3. \"Wennst vorbei willst, musst ein bisschen Stoff geben!\""}]'::jsonb, 'aufs Schwammal schdeing'),
  ('dea-is-so-fett-dea-schwammaed-wiara-schiffanaakl-im-schduam', 'Dea is so fett - dea schwammäd wiara Schiffanaakl im Schduam!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der ist so fett - der schwamelt wie ein Schiffanakl im Sturm!', '[{"kategorie": "wörtlich", "text": "\"Der ist betrunken bis obenhin - torkelt wie ein Kahn im Sturm!\"  2. \"Der ist so fett, der hat mehr Schlagseite als ein alter Kutter!\"  3. \"Der ist sturzbetrunken - liegt quer wie ein Frachter in der Brandung!\""}]'::jsonb, ''),
  ('waunn-i-mei-schwammae-hob-fueuel-i-mi-ned-bsoffn-nua-optimistisch', 'Waunn I mei Schwammä hob, füül I mi ned bsoffn - nua optimistisch!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn ich mein Schwamml hab, fühl ich mich nicht besoffen - nur optimistisch!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich mein Räuschchen hab, bin ich nicht besoffen - nur optimistisch!\"  2. \"Mit einem Schwamml fühl'' ich mich nicht betrunken, nur gut gelaunt!\"  3. \"Wächst mir ein Schwammerl, dann hab ich keinen Rausch, sondern nur ordentlich Selbstvertrauen!\""}]'::jsonb, ''),
  ('da-schwammaetoomal-hod-an-dauapeegl-dea-is-valaesslicha-ois-de-uazeit', 'Da Schwammätoomal hod an Dauapeegl, dea is valässlicha ois de Uazeit!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Schwammelthomerl hat ''nen Dauerpegel, der ist verlässlicher als die Uhrzeit!', '[{"kategorie": "wörtlich", "text": "\"Der Schwammerlthomas läuft auf Dauerschwips, genauer als jede Uhr!\"  2. \"Der Pegel von diesem Rauschbruder ist stabiler als ein Schweizer Uhrwerk!\"  3. \"Der Thomerl braucht keine Uhr – sein Pegel sagt ihm, wie spät es ist!\""}]'::jsonb, ''),
  ('nuechtan-hod-den-schwammaetandla-ned-amoi-noo-sei-eigane-muada-gseeng', 'Nüchtan hod den Schwammätandla ned amoi noo sei eigane Muada gseeng!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Nüchtern hat diesen Schwammeltandler nicht einmal noch seine eigene Mutter gesehen!', '[{"kategorie": "wörtlich", "text": "\"Nüchtern hat diesen Rauschbruder nicht einmal noch seine eigene Mutter gesehen!\"  2. \"Als Rauschkugel muss er schon geboren worden sein – denn nüchtern gesehen hat ihn noch keiner!\"  3. \"Wenn dieser Dauertrinker einmal in seinem Leben nüchtern wär, müsste er sich sogar seiner Mutter neu vorstellen!\""}]'::jsonb, ''),
  ('wiad-schwammaln-ausn-boodn-schiassn', 'wiad Schwammaln ausn Boodn schiassn', '', '', '', 'Wiener Sprüche, die sitzen!', 'wie die Schwammerln aus dem Boden schießen', '[{"kategorie": "wörtlich", "text": "\"wie Pilze aus dem Boden schießen\""}, {"kategorie": "", "text": "\"sich explosionsartig vermehren\""}, {"kategorie": "", "text": "\"über Nacht wie Unkraut aus der Erde wachsen\""}, {"kategorie": "", "text": "\"sich lawinenartig ausbreiten\""}, {"kategorie": "", "text": "\"plötzlich wie aus dem Nichts da sein\""}]'::jsonb, 'Kaum zoid aana a Rundn, schiassn de Duaschtign wia Schwammaln ausn Boodn!'),
  ('kaum-zoid-aana-a-rundn-schiassn-de-duaschtign-wia-schwammaln-ausn-boodn', 'Kaum zoid aana a Rundn, schiassn de Duaschtign wia Schwammaln ausn Boodn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Kaum zahlt einer ''ne Runde, schießen die Durstigen wie Schwammerln aus dem Boden!', '[{"kategorie": "wörtlich", "text": "\"Sobald einer ''ne Runde spendiert, schießen die Durstigen wie Pilze aus dem Boden!\"   2. \"Kaum steht ''ne Runde, tauchen lauter Durstige wie aus dem Nichts auf!\"  3. \"Bestellt einer ''ne Runde, kriechen die Durstigen plötzlich aus allen Winkeln und Ecken hervor!\""}]'::jsonb, 'wiad Schwammaln ausn Boodn schiassn'),
  ('a-schwammalbrocka-oone-koab-is-wiara-fischa-oone-netz', 'A Schwammalbrocka oone Koab is wiara Fischa oone Netz!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein Schwammerlbrocker ohne Korb ist wie ein Fischer ohne Netz!', '[{"kategorie": "wörtlich", "text": "\"Ein Pilzpflücker ohne Korb ist wie ein Fischer ohne Netz!\"  2. \"Wer Pilze sammelt, braucht einen Korb – sonst geht er leer aus!\"  3. \"Ohne Korb keine Schwammerl!\""}]'::jsonb, ''),
  ('fia-des-projekt-brauchsd-visionaeaere-kaane-schwammalbrocka', 'Fia des Projekt brauchsd Visionääre, kaane Schwammalbrocka!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Für dieses Projekt brauchst du Visionäre, keine Schwammerlbrocker!', '[{"kategorie": "wörtlich", "text": "\"Für dieses Projekt brauchst du Visionäre, keine Erbsenzähler!\"  2. \"Bei einem solchen Projekt sind Visionäre gefragt, keine Buchhaltertypen!\"  3. \"Große Ziele erreicht man nicht mit spießigem, sondern nur mit großem Denken!\""}]'::jsonb, ''),
  ('aum-wochneend-foin-de-schwammalsuacha-iwan-woid-hea-wia-de-heischreckn', 'Aum Wochneend foin de Schwammalsuacha iwan Woid hea wia de Heischreckn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Am Wochenende fallen die Schwammerlsucher über den Wald her wie die Heuschrecken!', '[{"kategorie": "wörtlich", "text": "\"Am Wochenende fallen die Pilzsammler über den Wald her wie die Heuschrecken!\"  2. \"Am Wochenende wird der Wald von Pilzsammlern regelrecht abgeerntet!\"  3. \"Sobald Samstag ist, wird der Wald von Pilzsammlern geplündert und leergeräumt!\""}]'::jsonb, ''),
  ('a-schwammalsuacha-siichd-nua-in-boodn-vua-seine-fiass-owa-nii-in-gaunzn-woid', 'A Schwammalsuacha siichd nua in Boodn vua seine Fiass, owa nii in gaunzn Woid!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Schwammerlsucher sieht nur den Boden vor seinen Füßen, aber nie den ganzen Wald!', '[{"kategorie": "wörtlich", "text": "\"Ein Pilzsammler sieht nur den Boden vor seinen Füßen, aber nie den ganzen Wald!\"  2. \"Der Pilzsammler denkt nach unten, nicht nach vorne!\"  3. \"Detailblick ohne Weitblick ist Blindheit!\""}]'::jsonb, ''),
  ('oone-zuuz-schloofd-s-bauxal-nua-schwea-ei', 'Oone Zuuz schloofd s''Bauxal nua schwea ei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ohne Zutz schläft das Bauxerl nur schwer ein!', '[{"kategorie": "wörtlich", "text": "\"Ohne Schnuller schläft das Baby nur schwer ein!\"  2. \"Ohne Luller findet das Baby nur schwer in den Schlaf!\"  3. \"Fehlt der Schnuller, tut sich das Baby mit dem Einschlafen so richtig schwer!\""}]'::jsonb, ''),
  ('friara-hod-ma-denan-gschroppn-an-moonzuuz-ins-goschal-gschdeckd-waunns-gschrian-haum-und-daunn-haums-gschloofn-wiara-baea-im-winta', 'Friara hod ma denan Gschroppn an Moonzuuz ins Goschal gschdeckd, waunns gschrian haum - und daunn haums gschloofn wiara Bäa im Winta!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher hat man den Gschrappen einen Mohnzutz ins Goscherl gesteckt, wenn sie geschrien haben - und dann haben sie geschlafen wie ein Bär im Winter!', '[{"kategorie": "wörtlich", "text": "\"In früheren Zeiten hat man den kleinen Kindern einen ''Mohnschlecker'' in den Mund geschoben, wenn sie geschrien haben - und dann haben sie geschlafen wie ein Bär im Winter!\"  2. Früher hat man schreienden Kindern einen Mohnschlecker gegeben, dann war Ruhe bis zum Morgengrauen!  3. Bekam das Kind einen Mohnnuckel, war meist schnell Ruhe in der Stube!"}]'::jsonb, ''),
  ('seitdem-a-aum-moonzuuz-haengd-rennd-bei-eam-ollas-laungsauma', 'Seitdem a aum Moonzuuz hängd, rennd bei eam ollas laungsauma!', '', '', '', 'Wiener Gaunersprache', 'Seitdem er am Mohnzutz hängt, rennt bei ihm alles langsamer!', '[{"kategorie": "wörtlich", "text": "\"Seit er am Mohnschnuller hängt, lauft bei ihm alles langsamer!\"  2. \"Seitdem er sich mit Opium zudröhnt, läuft er nur noch auf halber Geschwindigkeit!\"  3. \"Seit er opiumabhängig ist, wirkt er geistig und körperlich verlangsamt!\""}]'::jsonb, ''),
  ('mit-aana-paunzaschoklaad-im-bluad-hoidst-de-gaunze-nochd-locka-duach', 'Mit aana Paunzaschoklaad im Bluad hoidst de gaunze Nochd locka duach!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Mit einer Panzerschokolade im Blut hältst du die ganze Nacht locker durch!', '[{"kategorie": "wörtlich", "text": "\"Mit Panzerschokolade im Blut bleibt man die ganze Nacht wach - die hält einen stundenlang auf den Beinen!\"  2. \"Hast du Panzerschokolade im Blut, kennt die Nacht kein Ende!\"  3. \"Auf Panzerschoko läufst du, bis der übernächste Tag anklopft!\""}]'::jsonb, ''),
  ('host-marschiapuiva-im-bluad-draad-da-mual-weida-aa-waunn-da-tank-laeaea-is', 'Host Marschiapuiva im Bluad, draad da Mual weida, aa waunn da Tank lääa is!', '', '', '', 'Wiener Gaunersprache', 'Hast du Marschierpulver im Blut, dreht der Murl weiter, auch wenn der Tank leer ist!', '[{"kategorie": "Gaunerjargon", "text": "\"Hast du Kokain im Blut, dreht der Motor weiter, auch wenn der Tank leer ist!\"  2. \"Hast du Marschierpulver im Saft, läuft der Antrieb weiter, obwohl die Reserven längst aufgebraucht sind!\"  3. \"Weißer Treibstoff lässt den Motor arbeiten, auch wenn keine Kraft mehr da ist!\""}]'::jsonb, ''),
  ('du-deppada-voidillo-du-host-da-s-gaunze-hian-schoo-laeaeagsoffn', 'Du deppada Voidillo - du host da s''gaunze Hian schoo lääagsoffn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du depperter Volldillo - du hast dir das ganze Hirn schon leergesoffen!', '[{"kategorie": "wörtlich", "text": "\"Du hirnamputierter Volldillo - bei dir schwimmt im Schädel nichts außer Alkohol!\"  2. \"Du kaputtgesoffener Volltrottel - so leer im Schädel, da könnt'' man glatt Pfand drauf verlangen!\"  3. \"Du hirntotes Vollweh - du hast dein Hirn nicht versoffen, das liegt schon im Archiv - geistiger Todeszeitpunkt unbekannt!\""}]'::jsonb, ''),
  ('du-hiinichgsoffana-voiwappla-bei-dia-schwimmd-im-schaeaedl-nix-mea-aussa-aeuk', 'Du hiinichgsoffana Voiwappla - bei dia schwimmd im Schäädl nix mea aussa Äuk!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du hinniggesoffener Vollwappler - bei dir schwimmt im Schädel nichts mehr außer Alk!', '[{"kategorie": "wörtlich", "text": "\"Du kaputtgesoffener Vollwappler - du hast dir das ganze Hirn schon leergesoffen!\"  2. \"Du hirnamputierter Volltrottel - so leer im Schädel, da könnt'' man glatt Pfand drauf verlangen!\"  3. \"Du hirntotes Vollweh - du hast dein Hirn nicht versoffen, das liegt schon im Archiv - geistiger Todeszeitpunkt unbekannt!\""}]'::jsonb, ''),
  ('du-hiantooda-voitrottl-so-laeaea-im-schaeaedl-do-kennd-ma-glott-pfaund-drauf-valaungan', 'Du hiantooda Voitrottl – so lääa im Schäädl, do kennd ma glott Pfaund drauf valaungan!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du hirntoter Volltrottel - so leer im Schädel, da könnt'' man glatt Pfand drauf verlangen!', '[{"kategorie": "wörtlich", "text": "\"Du hirntotes Vollweh - du hast dein Hirn nicht versoffen, das liegt schon im Archiv - geistiger Todeszeitpunkt unbekannt!\"  2. \"Du kaputtgesoffener Vollwappler - du hast dir das ganze Hirn schon leergesoffen!\"  3. \"Du hirnamputierter Volldillo - bei dir schwimmt im Schädel nichts außer Alk!\""}]'::jsonb, ''),
  ('a-foischs-wuat-und-dea-wiad-narrisch-wiara-augschdochana-ochs', 'A foischs Wuat, und dea wiad narrisch wiara augschdochana Ochs!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein falsches Wort, und der wird narrisch wie ein angestochener Ochse!', '[{"kategorie": "wörtlich", "text": "\"Ein falsches Wort, und der geht hoch wie ein angestochener Ochse!\"  2. \"Ein falsches Wort, und der explodiert wie ein Pulverfass!\"  3. \"Du brauchst nur einmal schief zu schauen, und der wird wild wie ein Stier!\""}]'::jsonb, ''),
  ('dea-is-so-narrisch-dassa-nimma-waass-wo-vuan-und-hintn-is', 'Dea is so narrisch, dassa nimma waass, wo vuan und hintn is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der ist so narrisch, dass er nimmer weiß, wo vorn und hinten ist!', '[{"kategorie": "wörtlich", "text": "\"Der ist dermaßen in Rage, dass er nimmer weiß, wo vorn und hinten ist!\"  2. \"Der ist so außer sich, dass ihm komplett der Verstand aussetzt!\"  3. \"Der ist dermaßen wütend, dass er nicht mehr klar denken kann!\""}]'::jsonb, ''),
  ('ea-is-gaunz-narrisch-auf-oide-eisn-und-reed-von-nix-aundam', 'Ea is gaunz narrisch auf oide Eisn und reed von nix aundam!', '', '', '', 'Wiener Mechaniker-Slang', 'Er ist ganz narrisch auf alte Eisen und redet von nichts anderem!', '[{"kategorie": "wörtlich", "text": "\"Er ist völlig versessen auf alte Motorräder und redet von nichts anderem!\"  2. \"Er ist ganz verrückt nach alten Maschinen - hat nichts anderes im Kopf!\"  3. \"Er ist total heiß auf alte Motorräder - die sind sein Ein und Alles!\""}]'::jsonb, ''),
  ('a-so-a-narrische-fuchtl', 'A so a narrische Fuchtl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Eine so eine narrische Fuchtel', '[{"kategorie": "wörtlich", "text": "\"Was für ein jähzorniges Weibsbild!\"  2. \"Was für ein aufbrausendes Frauenzimmer!\"  3. \"Was für ein hysterisches Keppelweib!\""}]'::jsonb, ''),
  ('bist-du-d-narrisch', 'Bist du d''narrisch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bist du denn narrisch!', '[{"kategorie": "wörtlich", "text": "\"Das gibt’s doch nicht!\"  2. \"Das kann doch nicht wahr sein!\"  3. \"Bist du deppert!\"  4. \"Ich fass es nicht!\"  5. \"Ach du meine Güte!\""}]'::jsonb, ''),
  ('i-wea-narrisch', 'I wea narrisch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich werde narrisch!', '[{"kategorie": "wörtlich", "text": "\"Ich werde wahnsinnig!\"  2. \"Ich drehe durch!\"  3. \"Ich verlier'' den Verstand!\"  4. \"Ich raste aus!\""}]'::jsonb, ''),
  ('moch-mi-ned-narrisch', 'Moch mi ned narrisch!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mach mich nicht narrisch!', '[{"kategorie": "wörtlich", "text": "\"Mach mich nicht verrückt!\"  2. \"Bring mich nicht auf die Palme!\"  3. \"Mach mich nicht wahnsiinig!\""}]'::jsonb, ''),
  ('narrisches-schwammal', 'narrisches Schwammal', 'das', '', '', 'Grundwortschatz Wienerisch', 'narrisches Schwammerl', '[{"kategorie": "wörtlich", "text": "\"närrischer Pilz\" (von [[narrisch]]=\"verrückt\" und [[Schwammerl]]=\"Pilz\")"}, {"kategorie": "bot.", "text": "\"spitzkegeliger Kahlkopf\" (enthält den Wirkstoff Psilocybin und löst nach dem Verzehr rauschähnliche Sinneszustände aus), \"halluzinogener Pilz\", \"psychoaktiver Pilz\", (lateinischer Name:) \"Psilocybe semilanceata\""}, {"kategorie": "allg.", "text": "\"Rauschpilz\", \"Zauberpilz\", (englisch): \"magic mushroom\""}, {"kategorie": "fig.", "text": "\"daueraufgedrehte Person\", \"überdrehte Seele\", \"Energiebündel unter Dauerstrom\", \"Wirbelwind\", \"Quirlkopf\""}]'::jsonb, 'Des narrische Schwammal schaud so hoamlos aus - owa chemisch hodsas faustdick hinta de Lamöön!'),
  ('des-narrische-schwammal-schaud-so-hoamlos-aus-owa-chemisch-hodsas-faustdick-hinta-de-lamoeoen', 'Des narrische Schwammal schaud so hoamlos aus - owa chemisch hodsas faustdick hinta de Lamöön!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Das narrische Schwammerl schaut so harmlos aus - aber chemisch hat''s der Pilz faustdick hinter den Lamellen!', '[{"kategorie": "wörtlich", "text": "\"Der spitzkegelige Kahlkopf sieht so harmlos aus, hat’s aber chemisch faustdick hinter den Lamellen!\"  2. \"Ein unscheinbares Schwammerl, dieser spitzkegelige Kahlkopf -  aber unter seinen Lamellen geht chemisch die Post ab!\"  3. Klein, brav, Wiesenpilz – aber chemisch kracht’s beim spitzkegeligen Kahlkopf ordentlich unter den Lamellen!\""}]'::jsonb, 'narrisches Schwammal'),
  ('olle-reedn-vom-maedschig-maschruum-bei-uns-haasd-des-aafoch-narrisches-schwammal', 'Olle reedn vom''mädschig Maschruum'' - bei uns haasd des aafoch ''narrisches Schwammal''!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Alle reden vom ''Magic Mushroom'', bei uns heißt das einfach ''narrisches Schwammerl''!', '[{"kategorie": "wörtlich", "text": "\"Alle sagen ''Magic Mushroom'' – bei uns nennt man’s ''narrisches Schwammerl''!\"  2. \"Hipster sagen ''Magic Mushroom'', der Wiener sagt ''narrisches Schwammerl''!\"  3. \"Was andernorts ''Magic Mushroom'' heißt, ist bei uns das ''narrische Schwammerl''!\""}]'::jsonb, 'narrisches Schwammal'),
  ('des-is-ka-mensch-des-is-a-narrisches-schwammal-unta-dauaschdroom', 'Des is ka Mensch, des is a narrisches Schwammal unta Dauaschdroom!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das ist kein Mensch, das ist ein narrisches Schwammerl unter Dauerstrom!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Mensch, das ist ein Energiebündel auf Hochspannung!\"  2. \"Das ist kein normaler Mensch – das ist ein wilder Wirbelwind im Schleudergang!\"  3. \"Das ist kein Mensch - das ist ''ne Steckdose auf zwei Beinen!\""}]'::jsonb, 'narrisches Schwammal'),
  ('narrische-schwammaln-gfressn-haum', 'narrische Schwammaln gfressn haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'narrische Schwammerln gefressen haben', '[{"kategorie": "wörtlich", "text": "\"Rauschpilze gegessen haben\""}, {"kategorie": "fig.", "text": "\"außer Rand und Band sein\""}, {"kategorie": "", "text": "\"sich wild und verrückt gebärden\""}, {"kategorie": "", "text": "\"völlig aufgedreht sein\""}]'::jsonb, 'Fia di ned so auf - host narrische Schwammaln gfressn oda wos?'),
  ('fia-di-ned-so-auf-host-narrische-schwammaln-gfressn-oda-wos', 'Fia di ned so auf - host narrische Schwammaln gfressn oda wos?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Führ dich nicht so auf – hast narrische Schwammerln g’fressen oder was?', '[{"kategorie": "wörtlich", "text": "\"Hör auf, dich so aufzuführen – hast du narrische Schwammerln gefressen oder was?\"  2. \"Hör auf, dich so zu benehmen – hast du den Verstand verloren, oder was?\"  3. \"Was führst du dich denn so auf? - Bist du auf Speed oder was?\""}]'::jsonb, 'narrische Schwammaln gfressn haum'),
  ('narrische-schwammaln-gessn-haum', 'narrische Schwammaln gessn haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'narrische Schwammerln gegessen haben', '[{"kategorie": "wörtlich", "text": "\"Rauschpilze gegessen haben\""}, {"kategorie": "fig.", "text": "\"außer Rand und Band sein\""}, {"kategorie": "", "text": "\"sich wild und verrückt gebärden\""}, {"kategorie": "", "text": "\"völlig aufgedreht sein\""}]'::jsonb, 'Dea hupfd umanaund, fuchtld mit de Händ - ois häda narrische Schwammaln gessn!'),
  ('dea-hupfd-umanaund-fuchtld-mit-de-haend-ois-haeda-narrische-schwammaln-gessn', 'Dea hupfd umanaund, fuchtld mit de Händ - ois häda narrische Schwammaln gessn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der springt herum, fuchtelt mit de Händ – als hätt er narrische Schwammerln g’fressen!', '[{"kategorie": "wörtlich", "text": "\"Der springt herum, fuchtelt mit den Händen – als wär er auf Speed!\"  2. \"Der gebärdet sich so wild und verrückt, als hätte er was genommen!\"  3. \"Er verhält sich so chaotisch und unberechenbar, als ob er unter dem Einfluss von Drogen steht!\""}]'::jsonb, 'narrische Schwammaln gessn haum'),
  ('wia-narrisch', 'wia narrisch', '', '', '', 'Wiener Sprüche, die sitzen!', 'wie narrisch', '[{"kategorie": "wörtlich", "text": "\"wie verrückt\""}, {"kategorie": "", "text": "\"wie wild\", \"wie wahnsinnig\", \"wie ein Irrer\""}]'::jsonb, 'Des brennd wia narrisch auf da Haut!'),
  ('des-brennd-wia-narrisch-auf-da-haut', 'Des brennd wia narrisch auf da Haut!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das brennt wie narrisch auf der Haut!', '[{"kategorie": "wörtlich", "text": "\"Das brennt wie verrückt auf der Haut!\"  2. \"Das brennt wie Feuer auf der Haut!\"  3. \"Das brennt wie die Hölle!\""}]'::jsonb, 'wia narrisch'),
  ('dea-pleedad-wia-narrisch-duach-de-innanschdodt', 'Dea pleedad wia narrisch duach de Innanschdodt!', '', '', '', 'Wiener Mechaniker-Slang', 'Der pledert wie narrisch durch die Innenstadt!', '[{"kategorie": "wörtlich", "text": "\"Der rast wie ein Irrer durch die Innenstadt!\"  2. \"Der brettert durch die Innenstadt wie ein Wahnsinniger!\"  3. \"Der prescht wie wild durch die Innenstadt!\""}]'::jsonb, 'wia narrisch'),
  ('bist-narrisch', 'Bist narrisch?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Bist narrisch?', '[{"kategorie": "wörtlich", "text": "\"Bist du verrückt?\"  2. \"Bist du wahnsinnig?\"  3. \"Bist du noch bei Sinnen?\""}]'::jsonb, ''),
  ('auf-amoi-isa-narrisch-wuan', 'Auf amoi isa narrisch wuan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Auf einmal ist er narrisch geworden!', '[{"kategorie": "wörtlich", "text": "\"Plötzlich ist er verrückt geworden!\"  2. \"Auf einmal ist er übergeschnappt!\"  3. \"Mit einem Schlag hat er den Verstand verloren!"}]'::jsonb, ''),
  ('dea-muass-puudlnarrisch-sei-dassa-si-auf-so-an-schaas-iwahaupt-eilossd', 'Dea muass puudlnarrisch sei, dassa si auf so an Schaas iwahaupt eilossd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der muss pudelnarrisch sein, dass er sich auf so einen Schas überhaupt einlässt!', '[{"kategorie": "wörtlich", "text": "\"Der muss völlig durchgeknallt sein, dass er sich auf so einen Scheiß überhaupt einlässt!\"  2. \"Der ist doch komplett verrückt, wenn er bei so einem Mist mitmacht!\"  3. \"Wer sich auf so einen Blödsinn einlässt, muss völlig hinüber sein!\""}]'::jsonb, ''),
  ('da-kuatl-is-voi-weiwanarrisch-imma-hinta-an-jeedn-rock-hea', 'Da Kuatl is voi weiwanarrisch - imma hinta an jeedn Rock hea!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Kurtl ist voll weibernarrisch - immer hinter einem jeden Rock her!', '[{"kategorie": "wörtlich", "text": "\"Der Kurt ist total verrückt nach Frauen - der ist ständig hinter jedem Rock her!\"  2. \"Der Kurt hat nur Frauen im Kopf - der rennt jedem Rock nach!\"  3. \"Der Kurt denkt nur mit dem Unterleib - der springt jedes Weibsbild an!\""}]'::jsonb, ''),
  ('dea-hiasl-do-is-voi-futnarrisch-dea-denkt-nua-min-schwaunz', 'Dea Hiasl do is voi futnarrisch - dea denkt nua min Schwaunz!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der Hiasl da ist voll futnarrisch - der denkt nur mit dem Schwanz!', '[{"kategorie": "wörtlich", "text": "\"Der Dillo da ist komplett votzenfixiert - der denkt nur mit dem Schwanz!\"  2. \"Der Depp ist notgeil bis zum Anschlag - bei dem hängt das Hirn im Schritt!\"  3. \"Der Dolm da ist durch und druch schwanzgesteuert - bei dem ersetzt der Schwanz das Hirn!\""}]'::jsonb, ''),
  ('dea-woa-scho-imma-mentschanarrisch-des-is-kaana-zum-heiratn', 'Dea woa scho imma mentschanarrisch - des is kaana zum Heiratn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der war schon immer mentschanarrisch - das ist keiner zum Heiraten!', '[{"kategorie": "wörtlich", "text": "\"Der war schon immer verrückt nach Mädchen - das ist keiner zum Heiraten!\"  2. \"Der war schon immer hinter jedem Rock her – der ist nichts für den Traualtar!\"  3. \"Der ist so weibernarrisch - da brauchst an Trauschein erst gar nicht denken!\""}]'::jsonb, ''),
  ('de-woa-imma-scho-buamanarrisch-de-mauna-haums-ia-aafoch-autau', 'De woa imma scho buamanarrisch - de Mauna haums ia aafoch autau!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die war schon immer bubennarrisch – die Männer haben’s ihr einfach angetan!', '[{"kategorie": "wörtlich", "text": "\"Die war schon immer verrückt nach Jungs – Männer haben’s ihr einfach angetan!\"  2. \"Die war schon immer männerverrückt - bei Kerlen setzt ihr Hirn einfach aus!\"  3. \"Die war schon immer mannstoll - sobald ein Kerl auftaucht, vergisst sie alles andere!\""}]'::jsonb, ''),
  ('de-is-so-schwaunznarrisch-bei-dea-hod-da-untaleib-des-kommando-iwanumman', 'De is so schwaunznarrisch - bei dea hod da Untaleib des Kommando iwanumman!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die ist so schwanznarrisch - bei der hat der Unterleib das Kommando übernommen!', '[{"kategorie": "wörtlich", "text": "\"Die ist so schwanzfixiert - bei der hat der Unterleib das Kommando übernommen!\"  2. \"Die ist triebgesteuert bis zum Anschlag - da regiert nur noch der Unterleib!\"  3. \"Die ist mannstoll bis zum Gehtnichtmehr - bei der hat eindeutig der Unterleib das Sagen!\""}]'::jsonb, ''),
  ('de-is-ned-valiabd-de-is-aafoch-nua-beidlnarrisch', 'De is ned valiabd - de is aafoch nua beidlnarrisch!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die ist nicht verliebt - die ist einfach nur beidlnarrisch!', '[{"kategorie": "wörtlich", "text": "\"Die ist nicht verliebt - die ist einfach nur schwanzfixiert!\"  2. \"Das ist keine Liebe - bei der hat der Unterleib das Sagen!\"  3. \"Die ist mannstoll bis zum Gehtnichtmehr - die ist nicht verliebt, sondern triebgesteuert!\""}]'::jsonb, ''),
  ('es-gibt-mea-wappla-auf-dera-woeoed-ois-wia-echte-jass-de-wiakli-wos-kennan', 'Es gibt mea Wappla auf dera Wööd ois wia echte Jass, de wiakli wos kennan!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Es gibt mehr Wappler auf dieser Welt als echte Jass, die wirklich was können!', '[{"kategorie": "wörtlich", "text": "\"Es gibt mehr Ahnungslose auf dieser Welt als Menschen, die echt was draufhaben!\"  2. Die Welt ist voller Dilettanten, echte Fachleute sind selten!  3. Es gibt auf dieser Welt mehr Schaumschläger als echte Könner!"}]'::jsonb, ''),
  ('foa-weida-du-wappla-de-aumpae-is-seit-zeen-sekundn-auf-grean', 'Foa weida, du Wappla - de Aumpä is seit zeen Sekundn auf grean!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Fahr weiter, du Wappler, die Ampel ist seit zehn Sekunden auf grün!', '[{"kategorie": "wörtlich", "text": "\"Fahr weiter, du Idiot - die Ampel ist seit zehn Sekunden auf grün!\"  2. \"Gib Gas, du Blödmann - die Ampel steht seit zehn Sekunden auf grün!\"  3. \"Steig aufs Gas, du Trottel - grüner wird''s nimmer!\""}]'::jsonb, ''),
  ('des-is-so-a-wappla-dea-kriagd-nix-aufd-rei', 'Des is so a Wappla - dea kriagd nix aufd Rei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist so ein Wappler - der kriegt nichts auf die Reihe!', '[{"kategorie": "wörtlich", "text": "\"Das ist so ein Schussel - der kriegt nichts gebacken!\"  2. \"Das ist so ein [[Patscherl]] - der bringt überhaupt nichts zusammen!\"  3. \"Das ist so ein Tölpel - der bringt einfach nichts zustande!\""}]'::jsonb, ''),
  ('des-is-kaa-hackla-des-is-a-wappla', 'Des is kaa Hackla, des is a Wappla!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das ist kein Hackler, das ist ein Wappler!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Arbeiter, das ist ein Dilettant!\"  2. \"Das ist kein Könner, das ist ein Ahnungsloser!\"  3. \"Das ist kein Handwerker, sondern ein Vollpfosten!\""}]'::jsonb, ''),
  ('seita-bei-seina-oidn-woond-isa-zum-sitzpinkla-mutiad', 'Seita bei seina Oidn woond, isa zum Sitzpinkla mutiad!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Seit er bei seiner Alten wohnt, ist er zum Sitzpinkler mutiert!', '[{"kategorie": "wörtlich", "text": "\"Seit er mit seiner Freundin zusammenlebt, ist er zum Sitzpinkler mutiert!\"  2. \"Seit er bei seiner neuen Liebe eingezogen ist, pinkelt er nur noch im Sitzen!\"  3. \"Seit er bei seiner Lebensgefährtin wohnt, hat sie ihn vom Steh- zum Sitzpinkler umtrainiert!\""}]'::jsonb, ''),
  ('vagiss-den-dillo-des-is-a-sitzpinkla-oone-eia', 'Vagiss den Dillo - des is a Sitzpinkla oone Eia!', '', '', '', 'Wiener Gaunersprache', 'Vergiss den Dillo - das ist ein Sitzpinkler ohne Eier!', '[{"kategorie": "wörtlich", "text": "\"Vergiss den Sitzpinkler - der hat kein Rückgrat, keine Eier!\"  2. \"Vergiss den Idioten, das ist ein Schlappschwanz - große Klappe, nichts dahinter!\"  3. \"Vergiss den Sitzbrunzer - der zieht den Schwanz ein, sobald’s brenzlig wird!\""}]'::jsonb, ''),
  ('soboidsd-heiratsd-wiasd-vom-schdaeaebrunza-zum-sitzbrunza-umtreniad', 'Soboidsd heiratsd, wiasd vom Schdääbrunza zum Sitzbrunza umtreniad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sobald du heiratest, wirst du vom Stehbrunzer zum Sitzbrunzer umtrainiert!', '[{"kategorie": "wörtlich", "text": "\"Kaum ist man verheiratet, wird man vom Stehbrunzer zum Sitzbrunzer umtrainiert!\"  2. \"Ab der Hochzeit heißt''s: Pinkeln im Sitzen, statt im Stehen!\"  3. \"Mit dem Ehering kommt die Toiletten-Zuchtordnung: Stehmodus aus, Sitzpflicht an!\""}]'::jsonb, ''),
  ('mit-dem-brauchsd-ned-plaanan-des-is-a-sitzbrunza-mit-visitkoatn', 'Mit dem brauchsd ned plaanan - des is a Sitzbrunza mit Visitkoatn!', '', '', '', 'Wiener Gaunersprache', 'Mit dem brauchst du nicht zu planen - das ist ein Sitzbrunzer mit Visitenkarte!', '[{"kategorie": "wörtlich", "text": "\"Mit dem brauchst du kein Ding zu planen - das ist ein Sitzpinkler mit Visitenkarte!\"  2. \"Mit dem brauchst du keinen Coup zu starten – der ist ein Trockenschwimmer mit großer Klappe, aber nix dahinter!\"  3. \"Mit dem brauchst du keinen Plan auszuhecken – das ist ein Sitzpinkler ohne Eier!\""}]'::jsonb, ''),
  ('im-marxismus-woa-da-prolet-a-hackla-oone-eigntum-oiso-des-geengtaeu-von-an-besitzbuerga', 'Im Marxismus woa da Prolet a Hackla oone Eigntum - oiso des Geengtäu von an Besitzbürga!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Im Marxismus war der Prolet ein Hackler ohne Eigentum - also das Gegenteil von einem Besitzbürger!', '[{"kategorie": "wörtlich", "text": "\"Im Marxismus war der Prolet ein Arbeiter ohne Eigentum - also das Gegenteil von einem Besitzbürger!\"  2. \"Im Marxismus war der Prolet jemand, der nichts hatte außer seiner Arbeitskraft – anders als die Besitzbürger, die über Eigentum verfügten!\"  3. \"Als Prolet wurde im Marxismus der lohnabhängige Arbeiter ohne eigenen Besitz bezeichnet - im Gegensatz zur besitzenden Klasse, den Besitzbürgern!\""}]'::jsonb, ''),
  ('a-prolet-bleibd-a-prolet-do-hueuefd-kaa-aunzug-waunn-da-karakta-im-heisl-schwimmt', 'A Prolet bleibd a Prolet - do hüüfd kaa Aunzug, waunn da Karakta im Heisl schwimmt!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Prolet bleibt ein Prolet - da hilft kein Anzug, wenn der Charakter im Häusl schwimmt!', '[{"kategorie": "wörtlich", "text": "\"Ein Prolet bleibt ein Prolet – kannst ihn einkleiden wie du willst, wenn der Charakter im Scheißhaus schwimmt!\"  2. \"Ein Prolet bleibt ein Prolet – geschniegelt bis obenhin, aber der Charakter hängt im Klo!\"  3. \"Prolet bleibt Prolet - den kannst geschniegelt hinstellen, Benehmen kommt trotzdem keins raus!\""}]'::jsonb, ''),
  ('dera-ia-tiigaklaadl-is-echt-proolo', 'Dera ia Tiigaklaadl is echt proolo!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das Tigerkleid von ihr ist echt prolo!', '[{"kategorie": "wörtlich", "text": "\"Ihr Tigerkleid wirkt echt proletenhaft!\"  2. \"Ihr Tigerkleid ist echt niveaulos!\"  3. \"Dieses Tigerkleid von ihr hat echt was Vulgäres!\""}]'::jsonb, ''),
  ('den-sei-auftreedn-woa-echt-nua-proolo-und-peinlich', 'Den sei Auftreedn woa echt nua proolo und peinlich!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Auftreten von ihm war echt nur prolo und peinlich!', '[{"kategorie": "wörtlich", "text": "\"Sein Auftreten war einfach nur rüpelhaft und zum Kotzenpeinlich!\"  2. \"Sein Auftreten war so proletenhaft, dass es schon wehgetan hat!\"  3. \"Sein Auftreten war unterste Schublade - anstandslos und peinlich bis auf die Knochen!\""}]'::jsonb, ''),
  ('proolo', 'Proolo', 'der', '', '', 'Grundwortschatz Wienerisch', 'Prolo', '[{"kategorie": "wörtlich, Kurzform für", "text": "\"Prolet\" (vom lateinischen \"proletarius\"=\"Proletarier\", abgeleitet von \"proles\"=\"Nachkommenschaft\" [eigtl. \"besitzloser Bürger, der nur durch seine Nachkommenschaft zählt\"])"}, {"kategorie": "fig.", "text": "Primitivling, Ungebildeter, Unkultivierter, Rüpel, Banause (ungehobelter Mensch ohne Umgangsformen), [[Nadelstreifprolo]]"}]'::jsonb, 'Dera ia Tiigaklaadl is echt proolo!'),
  ('a-so-a-proolo-a-muadstrumm-goschn-und-kaane-manian', 'A so a Proolo - a muadstrumm Goschn und kaane Manian!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein so ein Prolo - eine mordstrumm Gosch''n und keine Manieren!', '[{"kategorie": "wörtlich", "text": "\"Was für ein Prolet - eine Riesenklappe und null Manieren!\"  2. \"Was für ein Primitivling – laut wie Sau, Anstand null!\"  3. \"Was für ein Rüpel – große Fresse, kein Benehmen!\""}]'::jsonb, ''),
  ('a-noodlschdreifproolo-bleibd-a-prolet-egal-wia-teia-sei-zwian-is', 'A Noodlschdreifproolo bleibd a Prolet, egal wia teia sei Zwian is!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Nadelstreifprolo bleibt ein Prolet, egal wie teuer sein Zwirn ist!', '[{"kategorie": "wörtlich", "text": "\"Ein Prolo im Nadelstreif bleibt ein Prolo – egal, was sein Stoff gekostet hat!\"  2. \"Teurer Zwirn macht aus einem Proleten noch lange keinen Gentleman!\"  3. \"Ein Nadelstreifprolo bleibt trotzdem ein Prolet – denn Geld poliert vielleicht den Anzug, aber sicher nicht den Charakter!\""}]'::jsonb, ''),
  ('proolo-toosta', 'Proolo-Toosta', 'der', '', '', 'Echte Wiener Schmähperlen', 'Prolo-Toaster', '[{"kategorie": "wörtlich", "text": "\"Proletentoaster\" (Determinativkompositum aus [[Prolo]]=\"Prolet\" und \"Toaster\"=\"Bräunungsautomat\")"}, {"kategorie": "scherzhaft für", "text": "Solarium, Sonnenstudio, Bräunungsstudio, \"Proletenbräuner\", \"Proletenröster\", [[Münz-Mallorca]]"}]'::jsonb, 'Na, dea Aubreende kummd ned ausn Ualaub - dea kummd direkt ausn Proolo-Toosta!'),
  ('na-dea-aubreende-kummd-ned-ausn-ualaub-dea-kummd-direkt-ausn-proolo-toosta', 'Na, dea Aubreende kummd ned ausn Ualaub - dea kummd direkt ausn Proolo-Toosta!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Nein, der Angebrannte kommt nicht aus''m Urlaub - der kommt direkt aus dem Prolo-Toaster!', '[{"kategorie": "wörtlich", "text": "\"Nein, die Rothaut kommt nicht aus''m Urlaub - der kommt direkt aus dem ''Proletenröster''!\"  2. \"Nein, das ist keine Urlaubsbräune - der Prolet wurde von der Steckdose im Solarium angebräunt!\"  3. \"Nein, das ist kein Sonnengebräunter, das ist ein Grillhähnchen - den haben sie zu lang in die Röhre geschoben!\""}]'::jsonb, ''),
  ('muenz-majorka', 'Münz-Majorka', 'das', '', '', 'Echte Wiener Schmähperlen', 'Münz-Mallorca', '[{"kategorie": "wörtlich", "text": "\"Müz-Mallorca\" (Determinativkompositum aus \"Münz\"=\"Münzautomat\" und \"Mallorca\"=\"Sonneninsel\")"}, {"kategorie": "scherzhaft für", "text": "\"Mallorca-Münzautomat\", \"Münzbräuner\", Solarium, Sonnenstudio, Bräunungsstudio, \"Proletenbräuner\", \"Proletenröster\", [[Proolo-Toosta]]"}]'::jsonb, 'Fünf Minuutn Münz-Majorka und schoo glaubsd, du woasd auf da Plaja!'),
  ('fuenf-minuutn-muenz-majorka-und-schoo-glaubsd-du-woasd-auf-da-plaja', 'Fünf Minuutn Münz-Majorka und schoo glaubsd, du woasd auf da Plaja!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Fünf Minuten Münz-Mallorca und schon glaubst du, du warst auf der Playa!', '[{"kategorie": "wörtlich", "text": "\"Kurz in Münz-Mallorca gegrillt - und schon hast du das Gefühl, du kommst direkt von der Playa!\"  2. \"Fünf Minuten Münzbräuner und du denkst, du hast Sand in den Schuhen!\"  3. \"Kurz im Prolo-Toaster rösten lassen und schon fühlt man sich wie am Ballermann!\""}]'::jsonb, ''),
  ('da-hoochgschissane-hoid-si-fia-wos-bessas-nua-waeura-mid-an-goidanan-leffae-im-maeu-aufd-woeoed-kumma-is', 'Da Hoochgschissane hoid si fia wos Bessas - nua wäura mid an goidanan Leffä im Mäu aufd Wööd kumma is!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Hochgeschissene hält sich für was Besseres - nur weil er mit einem goldenen Löffel im Maul auf die Welt gekommen ist!', '[{"kategorie": "wörtlich", "text": "\"Euer Hochwohlgeboren hält sich wohl für was Besonderes – bloß weil er mit ''nem goldenen Löffel im Maul geboren wurde!\"  2. \"Der Möchtegern-Adelige hält sich für die feine Gesellschaft, bloß weil er mit Goldbesteck ins Leben gestartet ist!\"  3. \"Das arrogante Arschloch spielt auf feiner Herr – nur weil er mit ’nem goldenen Löffel im Maul in die Welt gepurzelt ist!\""}]'::jsonb, ''),
  ('du-hoochgschissana-grosskopfada-min-goidleffae-im-oasch', 'Du hoochgschissana Grosskopfada min Goidleffä im Oasch!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du hochgeschissener Großkopferter mit''m Goldlöffel im Arsch!', '[{"kategorie": "wörtlich", "text": "\"Du hochwohlgeborener Großkotz mit''m Goldlöffel im Arsch!\"  2. \"Du hochnäsiger Schnösel mit Goldbesteck im Hintern!\"  3. \"Du pseudo-adeliger Bonzenarsch mit''m Goldlöffel im Hintern!\""}]'::jsonb, ''),
  ('dea-typ-is-a-hendlpuudara-schleimig-iwagriffig-und-total-kraunk', 'Dea Typ is a Hendlpuudara - schleimig, iwagriffig und total kraunk!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Typ ist ein Hendlpuderer – schleimig, übergriffig und total krank!', '[{"kategorie": "wörtlich", "text": "\"Der Typ ist ein Hühnerficker – ein schleimiger, übergriffiger und perverser Unzüchtler!\"  2. \"Der Typ ist ein widerlicher Perversling - schmierig, übergiffig und total abartig!\"  3. \"Der Typ ist ein perverser Sittenstrolch – schleimig, übergriffig bis zum Anschlag und komplett neben der Spur!\""}]'::jsonb, ''),
  ('dea-hendlpuudara-mochd-aus-jeeda-loesung-a-neichs-problem', 'Dea Hendlpuudara mochd aus jeeda Lösung a neichs Problem!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Dieser Hendlpuderer macht aus jeder Lösung ein neues Problem!', '[{"kategorie": "wörtlich", "text": "\"Dieser Hühnerficker macht aus jeder Lösung ein neues Problem!\"  2. \"Dieser Depp vom Dienst macht aus jeder Lösung ’ne neue Scheißbaustelle!\"  3. \"Dieser Vollpfosten ist ein wandelnder Totalschaden - der macht aus Gold Scheiße, jedes Mal!\""}]'::jsonb, ''),
  ('mit-dem-hendlpuudara-joogsd-heechstns-de-taubm-vom-doch', 'Mit dem Hendlpuudara joogsd heechstns de Taubm vom Doch!', '', '', '', 'Wiener Gaunersprache', 'Mit diesem Hendlpuderer jagst du höchstens die Tauben vom Dach!', '[{"kategorie": "wörtlich", "text": "\"Mit dieser Hühnerknarre erschreckst du höchstens Tauben!\"  2. \"Mit der Spielzeugpistole kannst du höchstens auf Taubenjagd gehen!\"  3. \"Mit dieser schwachkalibrigen Knarre machst du maximal Federvieh nervös, sonst nix!\""}]'::jsonb, ''),
  ('du-schleimada-iwagriffiga-hendlpuudara', 'Du schleimada, iwagriffiga Hendlpuudara!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du schleimerter, übergriffiger Hendlpuderer!', '[{"kategorie": "wörtlich", "text": "\"Du schleimiger, übergriffiger Hühnerficker!\"  2. \"Du schmieriger, perverser Unzüchtler!\"  3. \"Du schmieriger, notgeiler Perversling!\""}]'::jsonb, ''),
  ('de-scheanglade-daed-i-ned-amoi-schnacksln-waunn-sa-si-ind-puudawaesch-haut', 'De Scheanglade däd I ned amoi schnacksln, waunn sa si ind Puudawäsch haut!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Schernglerte würde ich nicht einmal schnackseln, wenn sie sich in d''Puderwäsche haut!', '[{"kategorie": "wörtlich", "text": "\"Die Schiefsichtige würd'' ich nicht einmal vögeln, wenn sie Reizwäsche anlegt!\"  2. \"Die Schernglerte reizt mich nicht mal, wenn sie sich komplett in Puderwäsche wickelt!\"  3. \"Dieses Schielauge kann sich in Spitze werfen, wie sie will – bei mir reißt die nix!\""}]'::jsonb, ''),
  ('de-gaunzn-maunda-woin-nii-wos-eanstes-imma-nua-a-bissl-schuastan', 'De gaunzn Maunda woin nii wos Eanstes - imma nua a bissl schuastan!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die ganzen Männer wollen nie was Ernstes - immer nur ein bisschen schustern!', '[{"kategorie": "wörtlich", "text": "\"Die ganzen Kerle wollen nie was Festes – immer nur ein bisschen vögeln!\"  2. \"Den ganzen Mannsbildern geht’s nie um Gefühle, immer nur ums Pudern!\"  3. \"Die Männer denken doch alle gleich: nix Beziehung, nur schnackseln!\""}]'::jsonb, ''),
  ('waunnsd-weida-so-schuastasd-samma-schnoella-beim-reparian-ois-beim-featigwean', 'Waunnsd weida so schuastasd, samma schnölla beim Reparian ois beim Featigwean!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wenn du weiter so schusterst, sind wir schneller beim Reparieren als beim Fertigwerden!', '[{"kategorie": "wörtlich", "text": "\"Wenn du so weiterpfuschst, sind wir schneller beim Reparieren als beim Fertigwerden!\"  2. \"Wennst weiter so murkst, reparieren wir länger, als wir bauen!\"  3. \"Bei deinem Gepfusche müssen wir immer wieder nachbessern, statt endlich abschließen zu können!\""}]'::jsonb, ''),
  ('friara-hod-so-mauncha-jungschbund-ghoffd-dass-a-mit-an-seidanan-kokettiafetzn-bei-de-mentscha-eindruck-schind', 'Friara hod so mauncha Jungschbund ghoffd, dass a mit an seidanan Kokettiafetzn bei de Mentscha Eindruck schind!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher hat so mancher Jungspund gehofft, dass er mit einem seidenen Kokettierfetzen bei den Mädels Eindruck schindet!', '[{"kategorie": "wörtlich", "text": "\"Einst meinte mancher Jungspund, mit einem seidenen Ziertuch die Gunst der Mädchen erringen zu können!\"  2. \"So mancher angehende Herr glaubte einst, durch ein sorgfältig gefälteltes Kavaliertuch bei den jungen Damen Eindruck zu schinden!\"  3. \"Ehedem hoffte so mancher Jüngling, mit seinem seidenen Einstecktuch Wohlgefallen beim weiblichen Geschlecht zu erregen!\""}]'::jsonb, ''),
  ('dea-feiabootschn-do-kokettiad-mid-an-jeedn-maunnsbueued-egal-ob-leedig-vageebm-oda-blind', 'Dea Feiabootschn do kokettiad mid an jeedn Maunnsbüüd - egal ob leedig, vageebm oda blind!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der Feuerpatschen da kokettiert mit einem jeden Mannsbild - egal ob ledig, vergeben oder blind!', '[{"kategorie": "wörtlich", "text": "\"Die Rothaarige da kokettiert mit jedem Kerl - egal ob ledig, vergeben oder blind!\"  2. \"Die Rotblonde da wirft jedem Mann schöne Augen zu – Status egal!\"  3. \"Die Rotschädlerte da baggert alles an, was Hosen trägt – egal ob ledig, verheiratet oder blind!\""}]'::jsonb, ''),
  ('de-oide-woa-gestan-so-puudalustig-de-haed-ollas-gnumma-wos-noo-schdee-kau', 'De Oide woa gestan so puudalustig - de häd ollas gnumma, wos noo schdee kau!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Alte war gestern so puderlustig - die hätt alles genommen, was noch stehen kann!', '[{"kategorie": "wörtlich", "text": "\"Die Alte war gestern dermaßen in Bumslaune – die hätt jeden genommen, der noch steht!\"  2. \"Die Frau war gestern spitz wie Nachbars Lumpi – so notgeil hab ich die noch nie erlebt!\"  3. \"Die Alte war gestern voll in Ficklaune - die hat alles angeflirtet, was nicht bei drei auf''m Baum war!\""}]'::jsonb, ''),
  ('i-bin-heit-so-luadapustig-wia-schoo-laung-nimma-oiso-mei-haawara-loss-ma-de-puppn-taunzn', 'I bin heit so luadapustig wia schoo laung nimma - oiso, mei Haawara, loss ma de Puppn taunzn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich bin heut so luderpustig wie schon lang nimmer - also, mein Haberer, lassen wir die Puppen tanzen!', '[{"kategorie": "wörtlich", "text": "\"Ich bin heut so puderlustig wie schon lang nimmer - also, Kumpel, lassen wir die Puppen tanzen!\"  2. \"Ich bin heut so bumsfidel wie ewig nimmer – also los, Alter, machen wir die Nacht zum Tag!\"  3. \"Ich bin heute in Bumslaune wie schon lange nicht mehr - also, Bruder, lass uns Spaß haben, ab ins Vergnügen!\""}]'::jsonb, ''),
  ('a-puffn-in-da-toschn-mochd-no-laung-kaan-hoatn-hund', 'A Puffn in da Toschn mochd no laung kaan hoatn Hund!', '', '', '', 'Wiener Gaunersprache', 'Eine Puffe in der Tasche macht noch lange keinen harten Hund!', '[{"kategorie": "wörtlich", "text": "\"Eine Knarre in der Hosentasche macht noch lange keinen Boss!\"  2. \"Nur weil du eine Pistole einstecken hast, bist du noch lange kein Macher!\"  3. \"Ohne Eier hilft dir auch die Puffen nix!\""}]'::jsonb, ''),
  ('da-quaagl-schdinkd-wia-da-teifae-schmeckd-owa-gettlich', 'Da Quaagl schdinkd wia da Teifä, schmeckd owa gettlich!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der Quargel stinkt wie der Teufel, schmeckt aber göttlich!', '[{"kategorie": "wörtlich", "text": "\"Der Quargel stinkt wie die Sünde, schmeckt aber himmlisch!\"  2. \"Der Quargel, ein Käse mit ausgeprägter Reifungsnote, hat zwar einen üblen Geruch, dafür aber ist sein Geschmack vorzüglich!\"  3. \"Der Quargel - ein Frischkäse aus pasteurisierter Kuhmilch mit weicher, cremiger Konsistenz - riecht wie die Hölle, schmeckt aber köstlich!"}]'::jsonb, ''),
  ('red-ned-so-an-quaagl', 'Red ned so an Quaagl!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Rede nicht so einen Quargel', '[{"kategorie": "wörtlich", "text": "\"Rede nicht so einen Stuss daher!\"  2. \"Erzähl nicht derartigen Unsinn!\"  3. [[Reed]] ned so an Schaas!"}]'::jsonb, ''),
  ('dea-quaagld-seit-zeen-minuutn-und-soogd-trotzdem-nix', 'Dea quaagld seit zeen Minuutn und soogd trotzdem nix!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der quargelt seit zehn Minuten und sagt trotzdem nix!', '[{"kategorie": "wörtlich", "text": "\"Der quatscht seit zehn Minuten, ohne dass was Konkretes dabei rauskommt!\"  2. \"Der schwafelt seit zehn Minuten, produziert aber nur heiße Luft!\"  3. \"Seit zehn Minuten schwurbelt er rum, ohne auf den Punkt zu kommen!\""}]'::jsonb, ''),
  ('deitlich-reedn-ned-quaagln', 'Deitlich reedn, ned quaagln!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Deutlich reden, nicht quargeln!', '[{"kategorie": "wörtlich", "text": "\"Deutlich sprechen, nicht nuscheln!\"  2. \"Mach den Mund auf beim Reden und murmel nicht in deinen Bart!\"  3. \"Sprich deutlich und nicht so, als hättest du Watte im Mund!\""}]'::jsonb, ''),
  ('hea-auf-mid-dera-quaaglarei-und-kumm-endlich-aum-punkt', 'Hea auf mid dera Quaaglarei und kumm endlich aum Punkt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hör auf mit dieser Quarglerei und komm endlich auf den Punkt!', '[{"kategorie": "wörtlich", "text": "\"Hör auf mit dieser Dummschwätzerei und komm endlich zur Sache!\"  2. \"Hör auf mit diesem Geschwafel  und komm endlich auf den Punkt!\"  3. \"Hör auf mit dieser Schwurbelei und red endlich Klartext!\""}]'::jsonb, '')
